const requests = createRequestClient(async (path,{method='GET',body,...options}={}) => {
  const headers = {...options.headers};
  if(body!==undefined && !(body instanceof FormData)) { headers['Content-Type']='application/json'; body=JSON.stringify(body); }
  if(method!=='GET' && state.csrf) headers['X-CSRF-Token']=state.csrf;
  const response=await fetch(path,{method,body,credentials:'same-origin',cache:'no-store',...options,headers});
  const result=await response.json().catch(()=>({}));
  if(!response.ok) { const e=new Error(requestErrorText(result.error||result.message||`${t('请求失败','Request failed')} (${response.status})`)); e.status=response.status;throw e; }
  return result;
});
const sessionReader = createSessionReader(() => api('/api/session',{fresh:true}));
const identityOf = value => `${value.admin?(value.super_admin?'admin':`staff:${value.staff?.id||''}`):value.user?.id||'guest'}:${value.csrf||''}`;
const authMutation = path => /^\/api\/(?:auth\/|role$|team\/invitations\/accept$|admin\/(?:auth\/bootstrap|passkeys\/.*\/finish))/.test(path);
function invalidateIdentity() {
  sessionReader.invalidate();requests.invalidate({abort:true});jobCache.clear();state.eligibility=null;
}
function announceIdentityChange() {try{localStorage.setItem('hireferry-session-change',`${Date.now()}:${Math.random()}`);}catch{}}
async function api(path,{method='GET',body,fresh=false,cache,...options}={}) {
  method=method.toUpperCase();
  const requestIdentity=identityOf(state);
  const write=method!=='GET',identityChange=write&&authMutation(path);
  const changesProfile=write&&(path==='/api/profile'||path.startsWith('/api/profile/'));
  // Read receipts and idempotent room creation do not invalidate unrelated navigation reads.
  const changesData=write&&!/^\/api\/chat\/(?:platform$|conversations\/[^/]+\/read$)/.test(path)&&path!=='/api/markdown';
  if(identityChange)invalidateIdentity();else if(changesData){requests.invalidate();state.eligibility=null;}
  if(changesProfile)sessionReader.invalidate();
  try {
    const group=method==='GET'&&root.dataset?.navigationState==='loading'&&!options.prefetch&&!options.headers&&!['/api/session','/api/config'].includes(path)?`navigation:${state.render}`:undefined;
    const result=await requests.request(path,{method,body,group,...options,fresh:fresh||cache===false});
    if(identityChange){invalidateIdentity();announceIdentityChange();}
    else if(changesData)requests.invalidate();
    if(changesProfile)sessionReader.invalidate();
    return result;
  } catch(error) {
    if([401,403].includes(error.status)&&identityOf(state)===requestIdentity) {
      if(error.status===401&&(state.user||state.admin)) {
        const administrator=state.admin;
        resetPrivateView();
        // A background poll can discover expiry too. Remove private DOM in this same task.
        if(location.pathname.startsWith('/app'))void go('/login');
        else if(location.pathname==='/admin'&&administrator)void go('/admin');
        else void render();
      }else{requests.invalidate();sessionReader.invalidate();state.eligibility=null;}
    }
    if(error instanceof RequestTimeoutError)error.message=error.uncertain?t('请求超时，操作结果尚未确认。请刷新查看，再决定是否重试。','The request timed out and its result is unknown. Refresh to check before retrying.'):t('服务器响应超时。请检查网络后重试。','The server took too long to respond. Check your connection and try again.');
    throw error;
  }
}
async function session(renderVersion) {
  const s=await sessionReader.read({force:renderVersion===undefined});
  if(renderVersion===undefined||renderVersion===state.render){
    if(identityOf(state)!==identityOf(s)){requests.invalidate({abort:true});jobCache.clear();state.eligibility=null;}
    Object.assign(state,{user:s.user,admin:s.admin,super_admin:s.super_admin===true,staff:s.staff||null,bootstrap:s.bootstrap,csrf:s.csrf});
  }
  return s;
}
function resumeCliLogin(authenticated=false) {try{const path=takeCliReturn(sessionStorage,location.origin,state,authenticated);if(path){location.assign(path);return true;}}catch{/* Browser storage is optional. */}return false;}
function notify(message,error=false) {clearTimeout(toastTimer);document.querySelector('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'info':'check')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>document.querySelector('#toast-root').replaceChildren(),5500);}
function setBusy(el,busy) {if(!el)return;el.disabled=busy;el.setAttribute('aria-busy',String(busy));}
function go(path) {const next=new URL(path,location.href);if(next.origin!==location.origin)return;const changedPage=pageIdentity(location.pathname,qs().get('tab'))!==pageIdentity(next.pathname,next.searchParams.get('tab'));closeDialog();history.pushState({},'',next.pathname+next.search+next.hash);if(changedPage)window.scrollTo({top:0,behavior:'instant'});return render();}
function themeMenu() {return `<details class="theme-menu"><summary aria-label="${t('切换主题','Change theme')}" title="${t('主题','Theme')}">${icon('palette')}</summary><div class="theme-panel"><div class="palette-options" role="group" aria-label="${t('配色','Color palette')}">${[['blue','海蓝','Ocean blue'],['violet','紫罗兰','Violet'],['rose','玫瑰','Rose'],['amber','琥珀','Amber'],['teal','青碧','Teal']].map(([value,zh,en])=>`<button type="button" class="palette-swatch" data-palette-choice="${value}" aria-label="${t(zh,en)}" title="${t(zh,en)}" aria-pressed="false"><span class="swatch-color" aria-hidden="true">${icon('check')}</span></button>`).join('')}</div><div class="mode-options" role="group" aria-label="${t('外观','Appearance')}">${[['light','sun','浅色','Light'],['dark','moon','深色','Dark'],['system','monitor','跟随系统','System']].map(([value,glyph,zh,en])=>`<button type="button" data-theme-choice="${value}" aria-label="${t(zh,en)}" title="${t(zh,en)}" aria-pressed="false">${icon(glyph)}</button>`).join('')}</div></div></details>`;}
function header() {
  const workspace=(location.pathname==='/admin'&&state.admin)||(location.pathname.startsWith('/app')&&state.user);
  const navigation = `<a href="/#how" data-scroll="how">${t('服务流程','How it works')}</a><a href="/#pricing" data-scroll="pricing">${t('服务与定价','Pricing')}</a><a href="/cli" data-nav>CLI</a>`;
  if(workspace)return `<header class="site-header workspace-header" data-dom-key="site-header">${brand()}<div class="workspace-location"><span class="workspace-location-divider" aria-hidden="true">/</span>${state.admin?t('管理工作台','Administration'):t('我的工作台','Workspace')}</div><div class="nav-right"><a href="/contact" data-nav class="workspace-help">${icon('info')}<span>${t('帮助','Help')}</span></a>${themeMenu()}<button class="language" type="button" data-action="language" aria-label="${t('Switch to English','切换为中文')}">${t('EN','中文')}</button></div></header>${state.config?.development?`<div class="environment-banner workspace-environment" data-dom-key="environment">${t('测试环境 · 以下为测试资料','Test environment · Test data only')}</div>`:''}`;
  return `<header class="site-header page-width" data-dom-key="site-header">${brand()}<nav class="nav" aria-label="${t('主导航','Primary navigation')}">${navigation}</nav><div class="nav-right">${themeMenu()}<button class="language" type="button" data-action="language" aria-label="${t('Switch to English','切换为中文')}">${t('EN','中文')}</button><a class="button small" href="${state.admin?'/admin':state.user?'/app':'/login'}" data-nav>${state.admin?t('总控台','Control room'):state.user?t('我的工作台','My workspace'):t('登录 / 注册','Get started')} ${icon('arrow')}</a></div></header><nav class="mobile-site-nav page-width" data-dom-key="mobile-nav" aria-label="${t('了解聘渡','Explore HireFerry')}">${navigation}</nav>${state.config?.development?`<div class="environment-banner" data-dom-key="environment">${t('演示 / 开发环境 · 请勿提交真实个人资料','Demo / development environment · Please use test data')}</div>`:''}`;
}
function footer() {return `<footer class="footer page-width" data-dom-key="footer"><div class="footer-left">${brand(true)}<span>© ${new Date().getFullYear()} HireFerry <span class="footer-dot">/</span> ${t('让相遇，恰到好处。','Good people. Good possibilities.')}</span></div><nav class="footer-links" aria-label="${t('服务说明与联系','Service information and contact')}"><a href="/cli" data-nav>${t('CLI 与技能','CLI & skills')}</a><a href="/privacy" data-nav>${t('隐私','Privacy')}</a><a href="/terms" data-nav>${t('服务条款','Terms')}</a><a href="/refunds" data-nav>${t('退款政策','Refunds')}</a><a href="/contact" data-nav>${t('联系','Contact')}</a>${state.config?.support_email?`<a href="${esc(contactMailto())}" aria-label="${t('客服邮箱','Support email')}">${esc(contactEmail())}</a>`:''}<a href="${esc(state.config?.source_url||'https://github.com/TokenNotIncluded/hireferry')}" target="_blank" rel="noopener noreferrer">${t('源代码','Source')}</a></nav></footer>`;}
function heading(title,subtitle='',action='',eyebrow='') {return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;}
function empty(title,description,action='',ico='file') {return `<div class="empty-state"><span class="empty-icon">${icon(ico)}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;}
function notice(text,style='') {return `<div class="notice ${style}">${icon('info')}<div>${text}</div></div>`;}
function openDialog(content,{close=true,wide=false}={}) {closeDialog();lastFocus=document.activeElement;dialogs.innerHTML=`<div class="dialog-backdrop"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${close?`<button class="icon-button dialog-close" data-action="close-dialog" aria-label="${t('关闭','Close')}">${icon('close')}</button>`:''}${content}</section></div>`;document.body.style.overflow='hidden';const first=dialogs.querySelector('input:not([type=hidden]),textarea,select,button');first?.focus();trapListener=e=>{if(e.key==='Escape'&&close)closeDialog();if(e.key!=='Tab')return;const focusables=[...dialogs.querySelectorAll('a,button,input,textarea,select')].filter(x=>!x.disabled&&x.offsetParent);if(!focusables.length)return;const start=focusables[0],end=focusables.at(-1);if(e.shiftKey&&document.activeElement===start){e.preventDefault();end.focus();}else if(!e.shiftKey&&document.activeElement===end){e.preventDefault();start.focus();}};document.addEventListener('keydown',trapListener);}
function closeDialog() {const hadDialog=!!dialogs.querySelector('[role="dialog"]'),opener=lastFocus;lastFocus=null;dialogs.replaceChildren();document.body.style.overflow='';if(trapListener)document.removeEventListener('keydown',trapListener);trapListener=null;if(hadDialog&&opener?.isConnected)opener.focus?.();}
function confirmDialog(title,description,action,{danger=false}={}) {openDialog(`<div class="eyebrow">${t('请确认','PLEASE CONFIRM')}</div><h2 id="dialog-title">${title}</h2><p class="dialog-intro">${description}</p><div class="form-actions"><button class="button secondary" data-action="close-dialog">${t('取消','Cancel')}</button><button class="button ${danger?'danger':''}" id="confirm-action">${t('确认','Confirm')}</button></div>`);document.querySelector('#confirm-action').addEventListener('click',async e=>{setBusy(e.currentTarget,true);try{await action();closeDialog();}catch(error){notify(error.message,true);setBusy(e.currentTarget,false);}});}

function pricingSection() {
  const meta=currency(),publish=feeSettings('publish'),example=parseMinor('6000',meta.currency_decimals);
  const price=publish.mode==='free'?t('免费','Free'):publish.mode==='fixed'?money(publish.fixed_minor,meta):percent(publish.bps);
  const suffix=publish.mode==='salary_percent'?t('岗位月薪底薪','base monthly salary'):t('每次发布','per publication');
  let quote='—';try{quote=money(calculateFee(example,publish),meta);}catch{}
  return `<section class="section pricing-section" id="pricing"><div class="section-heading"><div><div class="eyebrow">SIMPLE. UPFRONT. FAIR.</div><h2>${t('费用简单，诚意透明。','Clear pricing. Clear intentions.')}</h2></div><p>${t('求职不收费。招聘费用在确认前说明。<br>无会员和月费，也不自动续费。','Free for job seekers. Hiring fees are shown before confirmation.<br>No memberships, monthly fees, or automatic renewal.')}</p></div><div class="pricing-grid"><article class="pricing-card seeker"><h3>${t('给求职者','For job seekers')}</h3><div class="price">${t('免费','Free')}<small>/ ${t('始终如此','always')}</small></div><p>${t('提交委托和平台私聊免费，跟进匹配也免费。','A search brief, private support, and introductions. All free.')}</p><div class="check-list"><div class="check-item">${icon('check')}${t('用邮箱开始，不需要手机号','Start with email. No phone number.')}</div><div class="check-item">${icon('check')}${t('简历不公开，仅匹配后共享','Your résumé is shared only after an introduction.')}</div></div><a href="/login?role=seeker" data-nav class="button secondary">${t('开启下一站','Start your next chapter')}${icon('arrow')}</a></article><article class="pricing-card"><div class="pricing-details"><div><h3>${t('招聘方开通','Employer activation')}</h3><div class="price">${money(pricing().onboarding_cents)}<small>/ ${t('一次','once')}</small></div><p>${t('一个账户，可以发布多个岗位。','One account. As many roles as you need.')}</p></div><div><h3>${t('每个招聘广告','Each job advertisement')}</h3><div class="price">${price}<small>/ ${suffix}</small></div><p>${publish.mode==='free'?t('确认发布后，委托平台持续寻找。','Confirm publication to start the search.'):t('一次支付，委托平台持续寻找。','One payment to start the search.')}</p></div></div><div class="price-calculator"><label for="salary-example">${t('例如底薪','Example salary')} · ${esc(meta.currency)}<input id="salary-example" type="number" min="${amountStep(meta)}" max="${amountValue(1000000000,meta)}" step="${amountStep(meta)}" value="6000" inputmode="decimal" aria-label="${esc(t('岗位月薪底薪','Base monthly salary')+' · '+meta.currency)}"></label><span>${t('发布费','Posting fee')} <strong class="price-result" id="salary-example-result">${quote}</strong></span></div><div class="pricing-note">${t(`只填固定底薪，不含奖金或提成。发布后锁定标题、币种与底薪。<br>描述修改：${feeRule('edit')}，最多 ${pricing().max_edits} 次。<br>招聘人数可免费无限次调整，填 0 暂停新匹配。`,`Use fixed base pay only, without bonuses or commission. Publication locks the title, currency, and salary.<br>Description updates: ${feeRule('edit')}. Up to ${pricing().max_edits} updates.<br>Hiring targets can be changed for free as often as needed. Set 0 to pause new introductions.`)}</div>${currencies().length>1?`<details class="currency-fees"><summary>${t('查看各币种费用','Fees by currency')}</summary>${currencyFeeTable()}<p class="help">${t('开通时可选择付款币种；岗位费用使用创建岗位时选择的币种，不作自动换算。','Choose an activation payment currency at checkout. Role fees use the currency selected when creating the role, without automatic conversion.')}</p></details>`:''}</article></div></section>`;
}
function currencyFeeTable() {
  return `<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('币种','Currency')}</th><th>${t('发布费','Publication')}</th><th>${t('每次描述修改','Each description update')}</th></tr></thead><tbody>${currencies().map(meta=>`<tr><th scope="row">${esc(meta.currency)}</th><td>${feeRule('publish',meta)}</td><td>${feeRule('edit',meta)}</td></tr>`).join('')}</tbody></table></div>`;
}

function home() {
  const stories = [
    {eyebrow:'HR AS A SERVICE',title:t('好工作。<br>对的人。<br><em>我们来牵线。</em>','Good work.<br>Great people.<br><em>We connect.</em>'),description:t('AI 原生的人才匹配平台。<br>人类 HR 与 AI HR 共同理解需求、初筛，<br>匹配到合适的人，再介绍你们认识。','An AI-native recruiting platform.<br>Human HR and AI HR understand your needs and screen for fit.<br>When there’s a match, we make the introduction.')},
    {eyebrow:'HUMAN + AI',title:t('先聊需求。<br>认真初筛。<br><em>合适，再介绍。</em>','First, we listen.<br>Then, we screen.<br><em>Meet your match.</em>'),description:t('第三方人类 HR 与 AI HR 一起寻找、匹配。<br>双方先与平台私聊，<br>建立匹配后，再开放对应资料与共同会话。','Third-party human HR and AI HR search and match together.<br>Each side starts with a private conversation.<br>Profiles and a shared room open after an introduction.')},
    {eyebrow:'NO MEMBERSHIPS. NO MONTHLY FEES.',title:t('求职免费。<br>招聘按次。<br><em>没有月费。</em>','Free to seek.<br>Pay as you hire.<br><em>No monthly fees.</em>'),description:t(`招聘账号 ${money(pricing().onboarding_cents)} 一次性开通。<br>岗位按公示规则付费，<br>无会员、无月费，不自动续费。`,`Activate an employer account once for ${money(pricing().onboarding_cents)}.<br>Job fees follow our published pricing.<br>No memberships, monthly fees, or automatic renewal.`)}
  ];
  return `<main id="main" class="home-main"><section class="home-story" aria-label="${t('认识聘渡','Discover HireFerry')}" aria-roledescription="${t('轮播','carousel')}"><div class="hero page-width"><div class="hero-copy"><div class="hero-slides">${stories.map((story,i)=>`<article class="hero-slide" data-story-slide="${i}" aria-hidden="${i!==0}"><div class="eyebrow"><span class="dot"></span>${story.eyebrow}</div><h1>${story.title}</h1><p class="hero-description">${story.description}</p></article>`).join('')}</div><div class="hero-actions"><a href="/login?role=seeker" data-nav class="button">${t('我在找工作','Find my next role')}${icon('arrow')}</a><a href="/login?role=employer" data-nav class="button secondary">${t('我想招人','Find my next hire')}${icon('arrow')}</a></div><div class="hero-footnote">${icon('check')}${t('求职者永久免费，无需手机号','Always free for job seekers. No phone number.')}</div></div><div class="sculpture-panel"><canvas id="sculpture" aria-label="${t('渡船、桥与罗盘随内容一起变换的三维粒子雕塑','Three-dimensional particle sculptures of a ferry, bridge, and compass, changing with the story')}"></canvas><div class="fallback" hidden>HireFerry · ${t('一起，驶向下一站','On to your next chapter')}</div></div><div class="story-bottom"><div class="scene-switch" role="group" aria-label="${t('切换介绍','Choose a chapter')}">${stories.map((story,i)=>`<button data-scene="${i}" aria-pressed="${i===0}" aria-label="${t(['平台介绍','初筛与匹配','收费方式'][i],['Introduction','Screening and matching','Pricing'][i])}">0${i+1}</button>`).join('')}<button class="sculpture-pause icon-button" data-action="pause" aria-label="${t('暂停动画','Pause animation')}">${icon('pause')}</button></div><p class="scene-caption" id="scene-caption">${t('每段旅程，都有人同行。','Every crossing, together.')}</p><a class="story-continue" href="#how" data-scroll="how">${t('向下探索','Keep exploring')}<span aria-hidden="true">↓</span></a></div></div></section><div class="home-flow page-width"><div class="trust-strip"><span class="trust-label">BUILT AROUND PEOPLE</span><span class="trust-item">${icon('person')}${t('人类 HR 与 AI HR 共同初筛','Human HR and AI HR screen for fit')}</span><span class="trust-item">${icon('shield')}${t('先匹配，再相互认识','Introductions before sharing')}</span><span class="trust-item">${icon('bot')}${t('AI 原生，开放连接','AI-native, open by design')}</span></div><section class="section" id="how"><div class="section-heading"><div><div class="eyebrow">A LITTLE LESS SEARCHING</div><h2>${t('把时间，留给更重要的事。','A little less searching.<br>A little more possibility.')}</h2></div><p>${t('不公开陈列简历和岗位。<br>先理解你的期待，再主动寻找合适的机会。','No public directories of profiles or roles.<br>We learn what matters, then actively search for a fit.')}</p></div><div class="steps"><article class="step"><span class="step-number">01 / SHARE</span><h3>${t('先和平台聊聊','Start with a conversation')}</h3><p>${t('一份简历，或一份岗位描述。<br>在私聊中告诉我们，你真正期待什么。','A résumé or a role description.<br>Tell us privately what you’re hoping to find.')}</p></article><article class="step"><span class="step-number">02 / CONNECT</span><h3>${t('我们持续去找','We keep looking')}</h3><p>${t('第三方人类 HR 与 AI HR 协作初筛、匹配。<br>持续寻找，认真跟进每次联系与进展。','Third-party human HR and AI HR screen and match together.<br>Research, contact, and follow-up stay on track.')}</p></article><article class="step"><span class="step-number">03 / MOVE FORWARD</span><h3>${t('合适，再介绍彼此','Meet when there’s a fit')}</h3><p>${t('匹配后才开放双方资料与共同会话。<br>平台继续陪伴，跟进每一个下一步。','An introduction opens profiles and a shared room.<br>We stay involved for the next steps.')}</p></article></div></section>${pricingSection()}<section class="home-bottom"><div><h2>${t('下一站，值得期待。','Your next chapter starts here.')}</h2><p>${t('你认真出发，我们认真搭桥。','You bring the ambition. We make the introduction.')}</p></div><a href="/login" data-nav class="button">${t('从这里开始','Let’s get started')}${icon('arrow')}</a></section></div></main>`;
}

let homeModules;
async function mountHome() {
  const canvas=document.querySelector('#sculpture');if(!canvas)return;
  const version=state.render;
  try{
    homeModules ||= Promise.all([import('./runtime/timeline.js'),import('./runtime/motion.js'),import('./scenes.js'),import('./home-story.js')]).catch(error=>{homeModules=null;throw error;});
    const [{createTimeline},{mountSculpture},{makeScenes},{mountHomeStory}]=await homeModules;
    if(version!==state.render||!canvas.isConnected)return;
  state.sculpture=mountSculpture(canvas,createTimeline(makeScenes(),{hold:8,morph:2}),{
    onState:s=>{const b=document.querySelector('[data-action=pause]');if(b){b.innerHTML=icon(s==='paused'?'play':'pause');b.setAttribute('aria-label',s==='paused'?t('继续动画','Resume animation'):t('暂停动画','Pause animation'));b.setAttribute('aria-pressed',String(s==='paused'));b.disabled=s==='reduced'||s==='unsupported';}if(s==='unsupported')document.querySelector('.fallback').hidden=false;}
  });
  state.homeStory=mountHomeStory(document.querySelector('.home-story'),{
    onPosition:position=>state.sculpture?.seek(position),
    captions:[t('每段旅程，都有人同行。','Every crossing, together.'),t('两端的期待，在这里相遇。','Two sides. One connection.'),t('为下一站，找到方向。','Find your next direction.')]
  });
  }catch{if(version===state.render){const fallback=document.querySelector('.fallback');if(fallback)fallback.hidden=false;}}
}

function sidebar(tab,admin=false) {
  const entries=admin?[
    ['overview','chart',t('总览','Overview')],['messages','message',t('消息','Messages')],['matches','board',t('匹配工作台','Matching')],['mandates','target',t('寻找委托','Search briefs')],['users','person',t('用户','People')],['jobs','briefcase',t('岗位','Jobs')],['orders','receipt',t('订单与流水','Orders')],...(state.super_admin?[['team','person',t('团队成员','Team members')],['agents','bot',t('平台 AI','Platform AI')],['keys','key',t('通行密钥','Passkeys')]]:[])
  ]:[
    ['messages','message',t('消息','Messages')],
    ...(state.user?.role==='seeker'?[['mandate','target',t('寻找委托','My search')]]:[]),
    ...(state.user?.role==='employer'?[['jobs','briefcase',t('我的招聘','My roles')]]:[]),
    ['profile',state.user?.role==='employer'?'person':'file',state.user?.role==='employer'?t('我的资料','My profile'):t('我的简历','My résumé')],['matches','link',t('我的匹配','Introductions')],['orders','receipt',t('订单','Orders')],['agents','bot',t('AI 连接','AI connections')],['webhooks','link',t('联动','Webhooks')]
  ];
  const item=([key,ico,label])=>`<a href="${admin?'/admin':'/app'}?tab=${key}" data-nav class="${tab===key?'active':''}"${tab===key?' aria-current="page"':''}>${icon(ico)}<span>${label}</span>${tab===key?'<span class="nav-current-dot" aria-hidden="true"></span>':''}</a>`;
  const primary=entries.slice(0,4),secondary=entries.slice(4);
  const cliConnection=admin&&!state.super_admin?'':`<a href="/oauth/connections">${icon('key')}<span>${t('命令行连接','Command-line connections')}</span></a>`;
  const logout=`<button type="button" data-action="logout">${icon('logout')}<span>${t('退出登录','Sign out')}</span></button>`;
  return `<aside class="sidebar workspace-sidebar" data-dom-key="sidebar"><div class="workspace-nav-label">${t('工作空间','WORKSPACE')}</div><nav class="sidebar-nav" aria-label="${t('工作台导航','Workspace navigation')}">${primary.map(item).join('')}<div class="workspace-secondary"><div class="workspace-nav-label">${t('管理与连接','MANAGE & CONNECT')}</div>${secondary.map(item).join('')}${cliConnection}</div><details class="workspace-more"><summary aria-label="${t('更多页面','More pages')}">${icon('board')}<span>${t('更多','More')}</span></summary><div class="workspace-more-menu">${secondary.map(item).join('')}${cliConnection}<a href="/contact" data-nav>${icon('info')}<span>${t('帮助与联系','Help & contact')}</span></a>${logout}</div></details></nav><div class="workspace-sidebar-foot"><a href="/contact" data-nav class="workspace-support">${icon('message')}<span>${t('需要帮忙？','Need a hand?')}<small>${t('联系聘渡','Contact HireFerry')}</small></span>${icon('arrow')}</a><div class="sidebar-user">${admin?`<span class="avatar">${icon('shield')}</span>`:avatar(state.user)}<div class="sidebar-account"><div class="sidebar-name">${admin?esc(state.staff?.name||t('聘渡管理团队','HireFerry team')):esc(state.user?.name||t('我的账户','My account'))}</div><div class="role-label">${admin?(state.super_admin?t('超级管理员','Super administrator'):t('团队员工','Staff')):roleText(state.user?.role)}</div></div><button class="icon-button" type="button" data-action="logout" aria-label="${t('退出登录','Sign out')}">${icon('logout')}</button></div><div class="workspace-policy-links"><a href="/privacy" data-nav>${t('隐私','Privacy')}</a><a href="/terms" data-nav>${t('条款','Terms')}</a></div></div></aside>`;
}
function shell(body,tab,admin=false) {return `<main id="main" class="page-width app-layout workspace-layout" data-workspace-page="${esc(tab)}">${sidebar(tab,admin)}<section class="app-content" tabindex="-1">${body}</section></main>`;}
function paymentProviders(record) {
  const code=currency(record).currency,configured=state.config?.payment_currencies;
  return (state.config?.providers||[]).filter(provider=>(!configured||(Array.isArray(configured[provider])&&configured[provider].includes(code)))&&(provider!=='waffo'||!state.config?.waffo_regions||waffoRegions(record).length>0));
}
const paymentMethodText = method => ({card:t('银行卡','Card'),applepay:'Apple Pay',googlepay:'Google Pay',wechat:t('微信支付','WeChat Pay'),alipay:t('支付宝','Alipay')})[method]||method;
const regionText = region => ({global:t('全球','Global'),china:t('中国','China')})[region] || region;
function waffoRegions(record) {
  const code=currency(record).currency;
  return Object.entries(state.config?.waffo_regions||{}).filter(([,settings])=>settings.currencies.includes(code));
}
function paymentModeNotice(provider='waffo') {
  return state.config?.payment_modes?.[provider]==='test'?`<p class="payment-test-notice" role="status">${icon('info')}<span>${t('测试模式 · 不会真实扣款','Test mode · No real charges')}</span></p>`:'';
}
function gatewayInputs(record,{hideRegions=false}={}) {
  const providers=paymentProviders(record),code=currency(record).currency;
  const regions=waffoRegions(record);
  return providers.length?`<div class="gateway-choice">${providers.map((name,i)=>`<label class="gateway-option"><input type="radio" name="provider" value="${esc(name)}" ${i===0?'checked':''}><span>${esc(providerText(name))}<small>${name==='stripe'?t('安全在线结账','Secure online checkout'):t('一次性支付','One-time payment')}</small></span></label>`).join('')}</div>${providers.includes('waffo')?`${!hideRegions&&regions.length?`<div class="field"><label for="payment-region">${t('Waffo Pancake 区域','Waffo Pancake region')}</label><select class="input" id="payment-region" name="payment_region">${regions.map(([name])=>`<option value="${esc(name)}">${esc(regionText(name))}</option>`).join('')}</select></div>`:''}${paymentModeNotice()}`:''}`:notice(t(`当前没有支持 ${code} 的在线支付方式。请更换币种或联系支持邮箱。`,`No online payment method is available for ${code}. Choose another currency or contact support.`),'warning');
}

function login() {return `<main id="main" class="page-width auth-wrap"><section class="auth-intro"><div class="eyebrow"><span class="dot"></span>WELCOME ABOARD</div><h1>${t('新的可能，<br>从认识你开始。','New possibilities.<br>Starting with you.')}</h1><p>${t('一个邮箱，一份期待。<br>无论你在寻找工作，还是寻找同伴，<br>我们都很高兴陪你一起。','An email address. A little ambition.<br>Whether you’re finding work or finding people,<br>we’re glad to be part of your next step.')}</p><div class="auth-quote">${t('不收集手机号。登录邮箱不对外公开。','No phone number. Your sign-in email stays private.')}</div></section><section class="auth-card"><h2>${t('欢迎来到聘渡','Welcome to HireFerry')}</h2><p class="subtitle">${t('登录或创建账户，只需一步。','Sign in or create your account.')}</p><a href="${state.config?.google_enabled?'/api/auth/google/start':'#'}" class="button secondary full" data-google-sign-in ${!state.config?.google_enabled?'aria-disabled="true" data-action="google-unavailable"':''}><span class="google-mark">G</span>${t('使用 Google 继续','Continue with Google')}</a>${state.config?.humangrant_enabled?humanGrant().loginButton():''}<div class="separator">${t('或使用邮箱','or use your email')}</div><form data-form="email-start"><div class="field"><label for="login-email">${t('邮箱地址','Email address')}</label><input class="input" id="login-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"></div><button type="submit" class="button full" ${state.config?.email_enabled===false?'disabled':''}>${t('发送登录验证码','Send a sign-in code')}${icon('arrow')}</button></form>${state.config?.email_enabled===false?`<p class="help">${t('邮箱登录暂未开放。','Email sign-in is not available yet.')}</p>`:''}<div class="auth-legal">${t('继续即表示你已阅读并同意','By continuing, you agree to our')} <a href="/terms" data-nav>${t('服务条款','Terms')}</a> ${t('及','and')} <a href="/privacy" data-nav>${t('隐私说明','Privacy notice')}</a>。</div></section></main>`;}
function emailCode(email,devCode) {const card=document.querySelector('.auth-card');card.innerHTML=`<h2>${t('查收你的邮箱','Check your inbox')}</h2><p class="subtitle">${t('验证码已发送至','We sent a sign-in code to')}<br><span class="auth-email">${esc(email)}</span></p><form data-form="email-verify"><input type="hidden" name="email" value="${esc(email)}"><div class="field"><label for="email-code">${t('登录验证码','Sign-in code')}</label><input class="input code-input" id="email-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]+" maxlength="12" placeholder="· · · · · ·" required><p class="help">${t('验证码短期有效，且只能使用一次。','This code expires soon and can only be used once.')}</p></div>${devCode?notice(`${t('仅开发测试环境','Development environment only')}: <strong>${esc(devCode)}</strong>`,'warning'):''}<button class="button full" type="submit">${t('确认并继续','Verify and continue')}${icon('arrow')}</button></form><div class="auth-legal"><button class="text-button" data-action="restart-login">${t('换一个邮箱','Use a different email')}</button></div>`;document.querySelector('#email-code').focus();}
function chooseRole() {openDialog(`<div class="eyebrow">YOUR NEXT CHAPTER</div><h2 id="dialog-title">${t('这次，你想寻找什么？','What brings you here?')}</h2><p class="dialog-intro">${t('选择你的身份，我们会为你准备合适的开始。','Choose your role. We’ll prepare the right start for you.')}</p><div class="role-options"><button class="role-card" data-action="role-seeker">${icon('person')}<strong>${t('我在找工作','I’m finding work')}</strong><span>${t('告诉平台期待，我们帮你持续找。','Share your expectations. We help with the search.')}</span><b>${t('永久免费','Always free')} →</b></button><button class="role-card" data-action="role-employer">${icon('briefcase')}<strong>${t('我想招人','I’m hiring')}</strong><span>${t('发布岗位，我们帮你认真寻找。','Share your role. We help find the right person.')}</span><b>${money(pricing().onboarding_cents)} ${t('一次性开通','one-time activation')} →</b></button></div><p class="help" style="margin-top:20px">${t('选择后，身份将与这个账户关联。招聘方完成开通后即可发布岗位，费用会在确认前列明。','Your choice is linked to this account. Employers can post after activation; any fee is shown before confirmation.')}</p>`,{close:false});}
function activationOptions(region) {
  const options=pricing().activation_currency_options||[{...currency(),onboarding_minor:pricing().onboarding_cents}];
  const settings=state.config?.waffo_regions?.[region];
  return settings?settings.currencies.map(code=>options.find(option=>option.currency===code)).filter(Boolean):options;
}
function activationCurrencyOptions(options,selected) {
  return options.map(option=>`<option value="${esc(option.currency)}" ${option.currency===selected?'selected':''}>${esc(option.currency)} · ${money(option.onboarding_minor,option)}</option>`).join('');
}
function employerActivation() {
  const regions=Object.keys(state.config?.waffo_regions||{}).filter(region=>activationOptions(region).length);
  const region=regions.find(region=>activationOptions(region).some(option=>option.currency===currency().currency))||regions[0];
  const options=activationOptions(region),selected=options.find(option=>option.currency===currency().currency)||options[0];
  const free=Number(selected?.onboarding_minor)===0;
  openDialog(`<div class="eyebrow">FOR EMPLOYERS</div><h2 id="dialog-title">${t('一起，找到对的人。','Find the right person.')}</h2><p class="dialog-intro">${t('一次性开通招聘方账户，之后可以发布多个岗位。每个岗位的发布费单独计算。','Activate your employer account once. Then publish multiple roles, each with its own posting fee.')}</p><form data-form="activate-employer" class="activation-checkout">${!free&&regions.length?`<fieldset class="payment-region-choice"><legend>${t('Waffo Pancake 区域','Waffo Pancake region')}</legend><div class="payment-region-options">${regions.map(name=>`<label><input type="radio" name="payment_region" value="${esc(name)}" ${name===region?'checked':''}><span>${icon(name==='global'?'globe':'wallet')}<strong>${esc(regionText(name))}</strong><small>${esc(state.config.waffo_regions[name].payment_methods.map(paymentMethodText).join(' · '))}</small></span></label>`).join('')}</div></fieldset>`:''}<div class="field"><label for="activation-currency">${t('付款币种','Payment currency')}</label><select class="input" name="currency" id="activation-currency">${activationCurrencyOptions(options,selected?.currency)}</select></div><div class="cost-summary activation-total"><div class="cost-row total"><span>${t('招聘方开通 · 一次性','Employer activation · one-time')}</span><strong data-activation-total>${money(selected?.onboarding_minor,selected)}</strong></div></div><div data-activation-gateway>${free?'':gatewayInputs(selected,{hideRegions:true})}</div><p class="cost-rule" data-activation-rule>${free?t('开通免费，确认后即可使用。','Activation is free and takes effect on confirmation.'):t('付款确认后自动开通。不自动续费，无月费。','Activates after payment confirmation. No renewals or monthly fees.')}</p><div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">${t('稍后再说','Maybe later')}</button><button type="submit" class="button" ${free||paymentProviders(selected).length?'':'disabled'}><span data-activation-submit>${free?t('确认开通','Activate account'):t('前往支付','Continue to payment')}</span>${icon('arrow')}</button></div></form>`);
}
function refreshActivationPayment(form) {
  const select=form.elements.currency,options=activationOptions(form.elements.payment_region?.value);
  const selected=options.find(option=>option.currency===select.value)||options[0];
  select.innerHTML=activationCurrencyOptions(options,selected?.currency);
  const free=Number(selected?.onboarding_minor)===0;
  form.querySelector('[data-activation-total]').textContent=money(selected?.onboarding_minor,selected);
  form.querySelector('[data-activation-gateway]').innerHTML=free?'':gatewayInputs(selected,{hideRegions:true});
  form.querySelector('[data-activation-rule]').textContent=free?t('开通免费，确认后即可使用。','Activation is free and takes effect on confirmation.'):t('付款确认后自动开通。不自动续费，无月费。','Activates after payment confirmation. No renewals or monthly fees.');
  form.querySelector('[type="submit"]').disabled=!selected||(!free&&!paymentProviders(selected).length);
  form.querySelector('[data-activation-submit]').textContent=free?t('确认开通','Activate account'):t('前往支付','Continue to payment');
}

async function profilePage() {
  const u=await api('/api/profile');
  return shell(`${heading(u.role==='seeker'?t('我的简历','My résumé'):t('团队资料','Team profile'),t('资料仅平台与已匹配的对方可见，不会公开展示。','Your profile is visible only to HireFerry and an introduced counterpart.'),'',u.role==='seeker'?'YOUR RÉSUMÉ':'YOUR PROFILE')}<form data-form="profile"><section class="panel"><div class="panel-header"><div><h2>${t('基本资料','Your profile')}</h2><p>${t('更新姓名、头像和联系方式。','Update your name, photo, and contact details.')}</p></div><span class="pill">${icon('shield')}${t('仅匹配后共享','Shared after introduction')}</span></div><div class="avatar-editor">${avatar(u,'large')}<div><div class="field-label">${t('你的头像','Your avatar')}</div><div class="avatar-actions"><label class="upload-label">${icon('upload')}${t('上传图片','Upload image')}<input type="file" id="avatar-upload" accept="image/png,image/jpeg,image/webp" hidden></label><button type="button" class="text-button" data-action="svg-avatar">${t('使用 SVG 文本','Use SVG text')}</button></div><p class="help">${t('PNG、JPG 或 WebP。图片会移除附带信息。','PNG, JPG or WebP. Image metadata is removed.')}</p></div></div><div class="grid-2"><div class="field"><label for="profile-name">${t('显示名称','Display name')}</label><input class="input" id="profile-name" name="name" value="${esc(u.name)}" maxlength="100" required></div><div class="field"><label for="profile-email">${t('联系邮箱','Contact email')}</label><input class="input" id="profile-email" type="email" name="public_email" value="${esc(u.public_email)}" placeholder="hello@example.com" maxlength="254"><p class="help">${t('仅平台和已匹配的对方可以看到。','Only HireFerry and an introduced counterpart can see this address.')}</p></div></div>${notice(`${t('登录邮箱','Sign-in email')}: ${esc(u.email)}<br>${t('仅用于登录，不向匹配方展示。无需提供手机号。','Used only for sign-in and never shared with a match. No phone number required.')}`)}${u.role!=='seeker'?'<input type="hidden" name="resume_md" value="">':''}</section>${u.role==='seeker'?`<section class="panel"><div class="panel-header"><div><h2>${t('经历与技能','Experience & skills')}</h2><p>${t('纯文本，支持 Markdown。没有复杂模板。','Plain text with Markdown. No complicated template.')}</p></div><span class="new-label">MARKDOWN</span></div><div class="tabs" role="tablist"><button type="button" data-action="resume-edit" role="tab" aria-selected="true">${t('编辑','Write')}</button><button type="button" data-action="resume-preview" role="tab" aria-selected="false">${t('预览','Preview')}</button></div><label class="field-label" for="resume-md">${t('简历内容','Résumé content')}</label><textarea id="resume-md" name="resume_md" class="input code resume-editor" maxlength="60000" placeholder="${esc(t('# 介绍一下自己\n\n## 我擅长的事\n- ...\n\n## 工作 / 项目经历\n- ...\n\n## 我期待的下一站\n...','# A little about me\n\n## What I do well\n- ...\n\n## Work / projects\n- ...\n\n## What comes next\n...'))}">${esc(u.resume_md)}</textarea><div id="resume-preview" class="markdown" hidden></div><p class="help resume-privacy">${icon('shield')}${t('匹配前，只有平台可以查看这份简历。','Before an introduction, only HireFerry can view this résumé.')}</p></section>`:''}<div class="form-actions"><p class="help">${t('不需要填写电话号码、身份证或家庭地址。','No phone number, identity document, or home address required.')}</p><button class="button" type="submit">${t('保存资料','Save profile')}${icon('check')}</button></div></form>`,'profile');
}
async function myJobs() {
  const trash=qs().get('view')==='trash';
  const r=await api((trash?'/api/my/jobs/trash':'/api/jobs/mine')+listParams());
  const jobs=r.items||[];
  jobCache.clear();jobs.forEach(job=>jobCache.set(job.id,job));
  const actions=trash?`<a href="/app?tab=jobs" data-nav class="button secondary">${icon('back')}${t('返回我的岗位','Back to my roles')}</a>`:`<div class="jobs-page-actions"><a href="/app?tab=jobs&view=trash" data-nav class="button secondary">${icon('trash')}${t('回收站','Trash')}</a><a href="/app/jobs/new" data-nav class="button">${icon('plus')}${t('发布新岗位','Post a new role')}</a></div>`;
  const head=heading(trash?t('岗位回收站','Deleted roles'):t('我的招聘','My roles'),trash?t('首次删除的岗位可以免费恢复一次，或直接永久删除。恢复后再次删除将永久清除。','A role’s first deletion can be restored once for free, or made permanent. Deleting it again after restoration is permanent.'):t('管理岗位与招聘人数，由平台寻找并介绍合适的人。','Manage your roles and hiring targets. HireFerry finds and introduces people.'),actions,trash?'YOUR RECENTLY DELETED ROLES':'YOUR OPPORTUNITIES');
  const rows=jobs.map(job=>`<article class="list-row job-row"><div class="job-row-main"><h3>${trash?esc(job.title):`<a href="/jobs/${encodeURIComponent(job.id)}" data-nav>${esc(job.title)}</a>`}</h3><div class="list-meta">${jobBadge(job)}<span class="job-salary">${money(job.salary_cents,job)} <small>/ ${t('月，底薪','month, base')}</small></span><span>${headcountText(job)}</span><span>${t('描述已修改','Description updates')} ${job.edits_used}</span></div><div class="row-actions job-row-links">${trash?`<button class="text-button" data-action="restore-job" data-id="${esc(job.id)}">${t('免费恢复','Restore for free')}</button><button class="text-button danger-text" data-action="permanently-delete-job" data-id="${esc(job.id)}">${t('永久删除','Delete permanently')}</button>`:`${job.status==='published'?`<a class="text-button" href="/app/jobs/${encodeURIComponent(job.id)}/edit" data-nav>${t('修改描述','Edit description')}</a>`:job.status==='draft'?`<a class="text-button" href="/app?tab=orders" data-nav>${t('查看待付订单','View pending order')} →</a>`:''}<button class="text-button ${Number(job.delete_count)>=1?'danger-text':''}" data-action="delete-job" data-id="${esc(job.id)}">${Number(job.delete_count)>=1?t('永久删除','Delete permanently'):t('删除岗位','Delete role')}</button>`}</div></div>${trash?'':headcountControl(job)}</article>`).join('');
  return shell(`${head}${!trash&&!state.user.employer_paid?notice(`${t('招聘方账户尚未开通。请先开通账户，即可发布招聘。','Your employer account is not active. Activate it to publish roles.')} <button class="text-button" data-action="role-employer">${t('开通账户','Activate account')} →</button>`,'warning'):''}${!trash?notice(t('人数可免费、无限次调整，不占描述修改次数。已发布岗位填 0 暂停新匹配，改回正数恢复；已有匹配和会话保留。人数由你手动维护。','Change the hiring target free of charge, as often as needed, without using a description update. For a published role, set 0 to pause new introductions; a positive number resumes them. Existing introductions and chats remain. You maintain the count yourself.')):''}<section class="panel"><div class="panel-header"><h2>${trash?t('岗位回收站','Role trash'):t('我的岗位','My roles')} <span class="muted">${jobs.length.toString().padStart(2,'0')}</span></h2><span class="new-label">${trash?t('可恢复一次','ONE RESTORATION'):t('底薪透明','BASE SALARY, UPFRONT')}</span></div>${jobs.length?`<div class="list">${rows}</div>${pagination(r.total??jobs.length,r.limit)}`:empty(trash?t('回收站是空的。','The trash is empty.'):t('第一个岗位，从这里开始。','Your first role starts here.'),trash?t('首次删除的岗位会显示在这里，永久删除的岗位无法恢复。','Roles appear here after their first deletion. Permanently deleted roles cannot be restored.'):t('写清工作内容、固定底薪与招聘人数，我们一起寻找合适的人。','Describe the work, fixed base salary, and hiring target. We’ll help find the right person.'),trash?'':`<a href="/app/jobs/new" data-nav class="button secondary">${icon('plus')}${t('创建岗位','Create a role')}</a>`,trash?'trash':'briefcase')}${trash?`<p class="help job-trash-note">${t('删除与恢复均不收费，也不自动退款。删除期间匹配资料与共同会话暂停访问，平台私聊保持独立；永久删除清除岗位标题与正文，保留必要订单和安全关联记录。','Deletion and restoration are free and do not trigger refunds. Deleted roles and shared rooms are inaccessible while in the trash; private platform chats stay separate. Permanent deletion erases the title and description while retaining necessary order and security records.')}</p>`:''}</section>`,'jobs');
}
async function jobEditor(id) {
  let job=null,terms=null;
  if(id){const result=await api(`/api/jobs/${encodeURIComponent(id)}`);job=result.job;terms=result.terms;}
  if(!state.user.employer_paid)return shell(`${heading(t('先开通，再出发。','Activate your account to begin.'))}<section class="panel">${empty(t('招聘方账户尚未开通','Your employer account is not active'),t(`开通费用为 ${money(pricing().onboarding_cents)}，开通后可以发布多个岗位。`,`Activation costs ${money(pricing().onboarding_cents)}. Once activated, you can post multiple roles.`),`<button class="button" data-action="role-employer">${t('开通账户','Activate account')}</button>`,'briefcase')}</section>`,'jobs');
  const locked=!!job,meta=currency(job),kind=locked?'edit':'publish',settings=feeSettings(kind,meta,terms),free=settings.mode==='free';
  const maximum=Number((terms||pricing()).max_edits),exhausted=locked&&job.edits_used>=maximum;
  const salary=job?.salary_cents??parseMinor('6000',meta.currency_decimals);
  let quote='—';try{quote=money(calculateFee(salary,settings),meta);}catch{}
  return shell(`<a href="/app?tab=jobs" data-nav class="back-link">${icon('back')}${t('返回我的招聘','Back to my roles')}</a>${heading(locked?t('让工作描述更清楚。','Make the role a little clearer.'):t('给好的人，一个好机会。','Give the right person a great opportunity.'),locked?t(`标题、币种与底薪已锁定。修改规则：${feeRule('edit',meta,terms)}，最多 ${maximum} 次。`,`The title, currency, and base salary are locked. Update rule: ${feeRule('edit',meta,terms)}. Up to ${maximum} updates.`):t('填写固定底薪，不含奖金、补贴、提成或预期收入。','Enter fixed base salary only, without bonuses, allowances, commission, or projected income.'))}${exhausted?notice(t('这个岗位已用完全部修改机会。','This role has used all available updates.'),'warning'):''}
  <form data-form="job" data-id="${esc(job?.id||'')}" data-fee-mode="${settings.mode}" data-fee-bps="${settings.bps}" data-fee-fixed="${settings.fixed_minor}" data-exhausted="${exhausted}"><section class="panel"><div class="field"><label for="job-title">${t('岗位名称','Job title')}</label><input class="input" id="job-title" name="title" maxlength="120" value="${esc(job?.title||'')}" placeholder="${esc(t('例如：Rust 后端工程师','For example: Rust backend engineer'))}" ${locked?'readonly':''} required></div><div class="grid-2"><div class="field"><label for="job-currency">${t('薪资与岗位费用币种','Salary and role-fee currency')}</label>${currencySelect(meta.currency,'currency','job-currency',locked)}<p class="help">${t('金额按所选币种填写，发布后锁定，不自动换算。','Enter amounts in the selected currency. Publication locks it; changing a selection does not convert amounts.')}</p></div><div class="field"><label for="job-salary" id="job-salary-label">${t('每月固定底薪','Fixed monthly base salary')} · ${esc(meta.currency)}</label><input class="input" id="job-salary" name="salary" type="number" min="${amountStep(meta)}" max="${amountValue(1000000000,meta)}" step="${amountStep(meta)}" inputmode="decimal" value="${amountValue(salary,meta)}" ${locked?'readonly':''} required><p class="help">${t('只填写实际保证支付的底薪。','Enter only the base salary you guarantee.')}</p></div></div>
  ${locked?`<div class="notice job-headcount-note">${icon('person')}<div>${headcountText(job)} · <a href="/app?tab=jobs" data-nav class="help-link">${t('招聘人数在我的岗位中免费调整，不占描述修改次数。','Change the hiring target for free in My roles, without using a description update.')}</a></div></div>`:`<div class="field job-headcount-create"><label for="job-headcount">${t('招聘人数','Hiring target')}</label><input class="input" id="job-headcount" name="headcount" type="number" min="0" max="${state.config?.limits?.max_job_headcount??1000000}" step="1" inputmode="numeric" value="1" required aria-describedby="job-headcount-help"><p class="help" id="job-headcount-help">${t('人数不影响发布费，可免费无限次调整。填 0 暂不招聘，改回正数即可恢复新匹配。','The target does not change the publication fee and can be changed for free as often as needed. Set 0 to pause new introductions and a positive number to resume.')}</p></div>`}
  <div class="field"><label for="job-jd">${t('工作描述 · Markdown','Job description · Markdown')}</label><textarea class="input code resume-editor" id="job-jd" name="jd_md" maxlength="60000" placeholder="${esc(t('## 你会做什么\n\n## 我们希望你\n\n## 工作方式与地点\n\n## 其他说明','## What you will do\n\n## What you bring\n\n## How and where we work\n\n## Anything else'))}" required>${esc(job?.jd_md||'')}</textarea><p class="help">${t('明确工作内容与要求，说明地点和工作方式。请勿索取身份证、手机号等无关信息。','Describe the work, requirements, location, and working arrangement. Avoid requesting unrelated personal information.')}</p></div>
  <div class="notice">${icon('info')}<div>${locked?`${t('剩余修改次数','Updates remaining')}: ${Math.max(0,maximum-job.edits_used)} / ${maximum}. `:''}${free?t('本次免费，确认后立即生效。','This operation is free and takes effect on confirmation.'):t('内容在支付确认后生效。修改订单未支付时，现有描述保持展示。','Changes take effect after payment is confirmed. The current description stays visible while an update is unpaid.')}</div></div><div class="cost-summary"><div class="cost-row"><span>${t('计费规则','Fee calculation')}</span><span id="job-fee-rule">${feeRule(kind,meta,terms)}</span></div><div class="cost-row total"><span>${locked?t('本次修改费用','Update fee'):t('本次发布费用','Publication fee')}</span><strong id="job-cost">${quote}</strong></div></div><p id="job-price-error" class="help" role="status" hidden></p><div data-payment-options data-currency="${esc(meta.currency)}" ${free?'hidden':''}>${free?'':gatewayInputs(meta)}</div><div class="form-actions"><a class="button secondary" href="/app?tab=jobs" data-nav>${t('返回','Back')}</a><button class="button" type="submit" data-job-submit ${exhausted||(!free&&!paymentProviders(meta).length)?'disabled':''}>${free?(locked?t('确认保存修改','Confirm update'):t('确认发布岗位','Confirm publication')):t('确认并前往支付','Confirm and continue to payment')}${icon('arrow')}</button></div></section></form>`,'jobs');
}
function refreshJobPrice(form) {
  if(!form)return;
  const selected=form.elements.currency?.value||currency().currency,meta=currency(selected),locked=!!form.dataset.id;
  const settings=locked?{mode:form.dataset.feeMode,bps:Number(form.dataset.feeBps),fixed_minor:Number(form.dataset.feeFixed)}:feeSettings('publish',meta);
  const paymentOptions=form.querySelector('[data-payment-options]');
  if(!locked&&paymentOptions.dataset.currency!==meta.currency){const previous=form.elements.provider?.value;paymentOptions.innerHTML=settings.mode==='free'?'':gatewayInputs(meta);paymentOptions.dataset.currency=meta.currency;if(previous&&paymentProviders(meta).includes(previous)&&form.elements.provider)form.elements.provider.value=previous;}
  const input=form.elements.salary;
  input.step=amountStep(meta);input.min=amountStep(meta);input.max=amountValue(1000000000,meta);
  form.querySelector('#job-salary-label').textContent=t('每月固定底薪','Fixed monthly base salary')+' · '+meta.currency;
  if(!locked)form.querySelector('#job-fee-rule').textContent=feeRule('publish',meta);
  let valid=true,error='';
  try{form.querySelector('#job-cost').textContent=money(calculateFee(centsInput(input.value,meta),settings),meta);}catch(cause){valid=false;error=cause.message==='Fee below one minor unit'?t(`当前比例计算的费用不足 ${money(1,meta)}，请检查底薪金额。`,`The calculated fee is below ${money(1,meta)}. Check the base salary.`):cause.message;form.querySelector('#job-cost').textContent='—';}
  const message=form.querySelector('#job-price-error');message.textContent=error;message.hidden=valid;
  form.querySelector('[data-job-submit]').disabled=!valid||form.dataset.exhausted==='true'||(settings.mode!=='free'&&!paymentProviders(meta).length);
}

function syncCurrencyFields(container=root) {
  const jobForm=container.querySelector('form[data-form="job"]');
  if(jobForm)refreshJobPrice(jobForm);
  for(const select of container.querySelectorAll('select[name="salary_currency"]'))service.updateSalaryCurrency(select);
}

function orderRefundDetails(order) {const refunded=Number(order.refunded_cents||0);return refunded>0?`<span class="order-refund">${t('已退','Refunded')} ${money(refunded,order)}</span><span class="order-net">${t('当前净额','Net amount')} ${money(Number(order.amount_cents)-refunded,order)}</span>`:'';}

async function ordersPage() {const r=await api('/api/orders');return shell(`${heading(t('订单与付款','Orders & payments'),t('查看订单、付款状态和历史费用。','Review your orders, payment status, and history.'),'','YOUR ORDERS')}<section class="panel">${r.items?.length?`<div class="list">${r.items.map(o=>`<article class="list-row"><div><h3>${kindText(o.kind)}</h3><div class="list-meta">${orderBadge(o)}<span>${date(o.created_at)}</span><span>${esc(providerText(o.provider))}</span>${o.live_mode===false&&o.provider!=='free'?`<span class="test-badge">${t('测试订单','Test order')}</span>`:''}</div><p class="order-number" style="margin-top:10px">${esc(o.id)}</p>${o.status==='pending'?`<div class="order-pending"><button class="text-button" data-action="pay-order" data-id="${esc(o.id)}">${t('继续支付','Continue payment')} →</button></div>`:''}${o.status==='paid_needs_review'?`<p class="help">${t('款项已收到，内容未自动更新。请联系管理员核对。','Payment was received; the update needs an administrator’s review.')}</p>`:''}</div><div class="order-amount"><strong>${money(o.amount_cents,o)}</strong>${orderRefundDetails(o)}</div></article>`).join('')}</div>`:empty(t('还没有订单。','No orders yet.'),state.user.role==='seeker'?t('求职者永久免费。你可以专心寻找下一站。','HireFerry is free for job seekers. Focus on your next chapter.'):t('你的开通、发布和修改费用会显示在这里。','Your activation, publication, and update payments will appear here.'),'','receipt')}</section>`,'orders');}
async function agentsPage() {
  const [r,eligibility,humanGrants]=await Promise.all([api('/api/tokens'),api('/api/ai/eligibility'),state.config?.humangrant_enabled?humanGrant().grantsPanel():'']);
  const allowed=!!eligibility.eligible;
  return shell(`${heading(t('让你的 AI，一起上船。','Bring your AI along.'),t('让 AI 协助沟通、整理需求与跟进。权限始终属于你。','Let AI help with conversations, expectations, and follow-ups. You remain in control.'),'','AI CONNECTIONS')}<section class="cli-connect-promo"><div><h2>${t('也可以，从终端连接。','Connect from your terminal, too.')}</h2><p>${t('安装 hfy，使用浏览器或设备码登录；再为你的 AI 助手安装 HireFerry 技能。','Install hfy, sign in with your browser or a device code, and add the HireFerry skill to your agent.')}</p></div><a href="/cli" data-nav class="button secondary small">${t('CLI 与技能安装','Install CLI & skill')}${icon('arrow')}</a></section>${humanGrants}<section class="panel"><div class="panel-header"><div><h2>${t('连接你的 AI 助手','Connect your AI assistant')}</h2><p>${t('通过 MCP 连接，或使用支持 WebMCP 的浏览器。','Connect through MCP, or use a browser that supports WebMCP.')}</p></div><span class="pill">MCP + WebMCP</span></div>${state.user.role==='employer'?notice(t(`招聘方需要至少一个符合发布时 AI 薪资门槛的已发布岗位，且发布权益有效、未关闭或删除。当前新岗位门槛：${(eligibility.currency_thresholds||currencies()).map(option=>money(option.employer_ai_min_salary_minor??eligibility.min_salary_cents,option)).join(' / ')}。原岗位保留发布时门槛；人数为 0 不影响资格。`,`Employers need an entitled, published role that meets its recorded AI salary threshold and is neither closed nor deleted. Current thresholds for new roles: ${(eligibility.currency_thresholds||currencies()).map(option=>money(option.employer_ai_min_salary_minor??eligibility.min_salary_cents,option)).join(' / ')}. Existing roles retain their publication threshold. A target of 0 does not remove eligibility.`),allowed?'':'warning'):notice(t('求职者免费使用 AI 连接。AI 只能访问你的资料、委托、会话及平台建立的匹配。','AI connections are free for job seekers. AI can access only your profile, search brief, conversations, and platform introductions.'))}${!allowed?`<div class="ai-locked"><span>${icon('key')}</span><h3>${t('完成条件后，AI 连接会开放。','AI access opens when the condition is met.')}</h3><p>${t('你仍然可以正常使用工作台，与平台沟通。','You can continue using the workspace and talking to HireFerry.')}</p><a class="button secondary" href="/app?tab=jobs" data-nav>${t('查看我的岗位','View my roles')}${icon('arrow')}</a></div>`:`<div class="field"><label>${t('MCP 服务地址','MCP server URL')}</label><div class="code-box">${esc(location.origin)}/mcp</div></div><p class="help">${t('连接方式：HTTP。使用下面创建的令牌，作为 Authorization: Bearer 请求头。令牌仅可操作你的账户。','Connection: HTTP. Use a token below as an Authorization: Bearer header. Tokens can only act on your account.')}</p><div class="notice" style="margin-top:20px">${icon('shield')}<div>${t('AI 发送的消息会标记为 AI 代发。平台私聊与匹配会话保持独立，收费操作仍需支付。','Messages sent by AI are labeled. Private and shared rooms remain separate, and paid actions still require payment.')}</div></div><form data-form="token" class="token-create-form"><div class="field"><label for="token-name">${t('连接名称','Connection name')}</label><input class="input" id="token-name" name="name" maxlength="80" placeholder="${esc(t('例如：我的 AI 助手','For example: My AI assistant'))}" required></div><button class="button secondary" type="submit">${icon('plus')}${t('创建访问令牌','Create access token')}</button></form><div id="new-token"></div>`}</section><section class="panel"><div class="panel-header"><h2>${t('已授权的连接','Authorized connections')}</h2></div>${r.items?.length?`<div class="list">${r.items.map(k=>`<div class="list-row"><div><h3>${esc(k.name)}</h3><div class="list-meta"><span>${t('创建于','Created')} ${date(k.created_at)}</span><span>${t('到期','Expires')} ${date(k.expires_at)}</span>${!allowed?`<span class="status closed">${t('当前不可用','Currently unavailable')}</span>`:''}</div></div><button class="text-button" data-action="revoke-token" data-id="${esc(k.id)}">${t('撤销','Revoke')}</button></div>`).join('')}</div>`:empty(t('你还没有连接 AI。','No AI connections yet.'),allowed?t('准备好时，创建一个令牌即可开始。','Create a token when you’re ready. Keep it private.'):t('满足条件后，可以创建个人 AI 连接。','Create a personal AI connection when eligible.'),'','bot')}</section>`,'agents');
}
async function jobsPage() { await go(state.user?'/app?tab=matches':'/login');return ''; }
async function jobDetail(id) {
  const {job,employer,jd_html}=await api(`/api/jobs/${encodeURIComponent(id)}`);
  const own=job.owner_id===state.user?.id;
  return `<main id="main" class="page-width public-layout"><section class="panel"><a class="back-link" href="/app?tab=${own?'jobs':'matches'}" data-nav>${icon('back')}${own?t('我的招聘','My roles'):t('我的匹配','My introductions')}</a><div class="job-heading"><div><h1>${esc(job.title)}</h1><div class="list-meta">${jobBadge(job)}<span>${headcountText(job)}</span><span>${t('发布于','Posted')} ${date(job.created_at)}</span></div></div><div class="job-salary">${money(job.salary_cents,job)} <small>/ ${t('月，底薪','month, base')}</small></div></div>${job.status==='published'&&jobHeadcount(job)===0?notice(t('这个岗位暂不接收新的匹配，已有匹配会话仍可继续。','This role is paused for new introductions. Existing introduction rooms remain available.')):''}<article class="markdown">${jd_html||''}</article></section><aside class="public-sidebar panel">${avatar(employer,'large')}<h3 style="margin-top:17px">${esc(employer?.name||t('招聘方','Employer'))}</h3><span class="pill">${icon('shield')}${t('仅匹配方可见','Shared with introduced parties')}</span>${employer?.public_email?`<a href="mailto:${encodeURIComponent(employer.public_email)}" class="contact-email">${esc(employer.public_email)}</a>`:`<p class="help" style="margin:16px 0">${t('尚未填写联系邮箱。','No contact email has been added.')}</p>`}<a class="button" href="/app?tab=matches" data-nav>${t('回到匹配会话','Back to introductions')}${icon('message')}</a><p class="help" style="margin-top:18px">${t('这份岗位由平台介绍给你。沟通与后续安排，可以在匹配会话中继续。','HireFerry has introduced this role. Continue the conversation and next steps in your introduction room.')}</p></aside></main>`;
}
async function peoplePage() { await go(state.user?'/app?tab=matches':'/login');return ''; }
async function personDetail(id) {
  const r=await api(`/api/people/${encodeURIComponent(id)}`);const u=r.user;
  return `<main id="main" class="page-width public-layout"><section class="panel"><a class="back-link" href="/app?tab=matches" data-nav>${icon('back')}${t('我的匹配','My introductions')}</a><div class="job-heading"><div class="sidebar-user" style="margin:0">${avatar(u,'large')}<div><h1>${esc(u.name)}</h1><p class="help">${t('平台介绍的求职者','Introduced by HireFerry')}</p></div></div></div><article class="markdown">${r.resume_html||''}</article></section><aside class="public-sidebar panel"><h3>${t('从一次交流开始。','Start a conversation.')}</h3><span class="pill">${icon('shield')}${t('仅匹配方可见','Shared with introduced parties')}</span>${u.public_email?`<a class="contact-email" href="mailto:${encodeURIComponent(u.public_email)}">${esc(u.public_email)}</a>`:`<p class="help">${t('尚未填写联系邮箱。','No contact email has been added.')}</p>`}<a class="button" href="/app?tab=matches" data-nav>${t('回到匹配会话','Back to introductions')}${icon('message')}</a><p class="help" style="margin-top:16px">${t('这份资料仅用于此次匹配。请尊重对方的隐私与选择。','This profile is shared for your introduction. Respect this person’s privacy and choices.')}</p></aside></main>`;
}
async function legal(kind) {
  const language=state.lang;
  const documentContent=await api(`/api/legal/${encodeURIComponent(kind)}?lang=${encodeURIComponent(language)}`);
  return renderLegal(documentContent,language);
}

function refundsPage() {
  return `<main id="main" class="page-width"><article class="prose"><div class="eyebrow">PAYMENTS, WITH CARE</div><h1 style="margin-top:18px">${t('退款问题，我们认真核对。','Refunds deserve a careful review.')}</h1><p>${t('这份说明适用于聘渡的招聘方开通、岗位发布和岗位描述修改订单。求职者使用服务免费。','This policy covers HireFerry employer activation, job publication, and job description update orders. The service is free for job seekers.')}</p><h2>${t('如何提出退款问题','How to ask about a refund')}</h2><p>${t('如有误付、重复付款、付款后服务未生效或其他订单异常，请发送邮件至支持邮箱，并提供订单号与简要情况说明。订单号可以在工作台的「订单」中找到。平台会根据订单记录和实际服务情况进行人工核对。','For a mistaken payment, duplicate payment, a service that did not activate after payment, or another order issue, email support with your order number and a brief description. Find the order number under Orders in your workspace. HireFerry reviews the order record and the service actually provided.')}</p><p><a href="${esc(contactMailto(t('HireFerry 订单与退款咨询','HireFerry order and refund inquiry')))}" class="contact-email-link">${esc(contactEmail())}</a></p><h2>${t('退款如何处理','How refunds are handled')}</h2><p>${t('退款经人工核对后，由平台通过支付服务商的商户后台处理。网站不直接发起退款。我们会在沟通中说明核对结果和后续处理方式；请保留订单号，以便继续跟进。','After review, HireFerry handles refunds through the payment provider’s merchant dashboard. The website does not initiate refunds directly. We explain the review result and next steps in our correspondence. Keep the order number for follow-up.')}</p><h2>${t('如何确认退款状态','How to confirm refund status')}</h2><p>${t('收到并验证 Waffo 成功退款通知后，订单会显示累计已退款金额、当前净额及「部分退款」或「已全额退款」状态。若原订单仍需人工核对，部分退款后可能继续显示「待人工核对」。失败或尚未确认的退款不会显示为成功，也不会扣减已记录的净收款。请在订单页面刷新核对。Stripe 退款请联系支持核对；本站暂不自动同步 Stripe 退款状态和净额。','After a successful Waffo refund notification is received and verified, the order shows the cumulative refunded amount, current net amount, and Partially refunded or Fully refunded status. An order that already needs manual review may retain Needs review after a partial refund. Failed or unconfirmed refunds are not shown as successful and do not reduce recorded net receipts. Refresh the order page to check. For Stripe refunds, contact support to verify the outcome; this website does not yet automatically update Stripe refund status or net amounts.')}</p><h2>${t('只提供必要的信息','Share only what is needed')}</h2><p>${t('退款咨询不需要提供银行卡卡号、手机号、验证码、通行密钥或 AI 访问令牌。请提供订单号与问题说明；支付信息由对应支付服务商处理。','A refund inquiry does not require a card number, phone number, sign-in code, passkey, or AI access token. Send the order number and a description of the issue. Payment information is handled by the relevant provider.')}</p><div class="policy-actions"><a href="/app?tab=orders" data-nav class="button secondary">${t('查看我的订单','View my orders')}${icon('receipt')}</a><a href="/contact" data-nav class="text-button">${t('联系与支持','Contact and support')} →</a></div></article></main>`;
}

function contactPage() {
  let origin=location.origin;
  try {const configured=new URL(state.config?.public_origin||origin);if(['https:','http:'].includes(configured.protocol))origin=configured.origin;}catch{}
  return `<main id="main" class="page-width"><article class="prose contact-page"><div class="eyebrow">A PERSON ON THE OTHER SIDE</div><h1 style="margin-top:18px">${t('有问题，我们在这里。','We’re here to help.')}</h1><p>${t('求职或招聘的问题，还有账户和订单问题，都可以从这里联系我们。','Reach out about your search, hiring, account, or order.')}</p><section class="panel contact-card"><span class="contact-icon">${icon('mail')}</span><div><h2>${t('支持邮箱','Support email')}</h2><a href="${esc(contactMailto())}" class="contact-email-link">${esc(contactEmail())}</a><p class="help">${t('订单与退款咨询请附上订单号和简要说明。','For orders and refunds, include your order number and a brief description.')}</p></div></section><h2>${t('已经有账户？在工作台继续聊。','Have an account? Continue in your workspace.')}</h2><p>${t('求职和招聘需求可以在你与平台的私聊中继续沟通。匹配后的双方交流使用独立会话，平台私聊历史保持分开。','Continue discussing your search or hiring needs in your private platform conversation. Introduced parties use a separate shared room; private platform histories stay separate.')}</p><a href="${state.user?'/app?tab=messages':'/login'}" data-nav class="button">${t('与平台沟通','Talk to HireFerry')}${icon('message')}</a><h2>${t('关于付款与隐私','Payments and privacy')}</h2><p>${t('请通过订单号说明支付问题，不需要发送银行卡卡号、手机号、登录验证码或访问令牌。你也可以通过支持邮箱提出资料更正或删除请求。','Use an order number to describe a payment issue. Do not send card numbers, phone numbers, sign-in codes, or access tokens. You may also email support to request a profile correction or deletion.')}</p><div class="policy-links"><a href="/refunds" data-nav class="help-link">${t('退款政策','Refund policy')}</a><a href="/privacy" data-nav class="help-link">${t('隐私说明','Privacy notice')}</a><a href="/terms" data-nav class="help-link">${t('服务条款','Terms')}</a></div><p class="contact-origin">${t('聘渡官网','HireFerry website')} · <a href="${esc(origin)}" class="help-link">${esc(origin)}</a></p></article></main>`;
}

async function render() {
  const navigationStarted=performance.now();
  requests.cancel(`navigation:${state.render}`);
  const version=++state.render;service.stopChat();state.homeStory?.dispose();state.homeStory=null;document.body.classList.toggle('home-page',location.pathname==='/');state.sculpture?.dispose();state.sculpture=null;document.documentElement.lang=state.lang==='en'?'en':'zh-CN';document.title=(state.config?.name||'HireFerry · 聘渡')+' · '+t('人才双向匹配服务','People-first hiring');
  const path=location.pathname,tab=qs().get('tab');
  const pageKey=pageIdentity(path,tab);
  const placeholderTab=path.startsWith('/human/')?'human-review':path.startsWith('/app/jobs/')?'editor':tab||(path==='/admin'?'overview':'messages');
  const pendingBody=()=>{const body=pagePlaceholder(placeholderTab,t('正在加载内容','Loading content'));if(path==='/admin'&&state.admin)return shell(body,tab||'overview',true);if(path.startsWith('/app')&&state.user)return shell(body,tab||'messages');return `<main id="main" class="page-width initial-placeholder">${body}</main>`;};
  root.dataset.navigationState='loading';root.dataset.navigationSequence=String(version);delete root.dataset.navigationReadyMs;delete root.dataset.navigationShellMs;
  const recordPaint=stage=>requestAnimationFrame(()=>{if(version!==state.render)return;root.dataset[stage==='shell'?'navigationShellMs':'navigationReadyMs']=(performance.now()-navigationStarted).toFixed(1);if(stage!=='shell')root.dataset.navigationState=stage;});
  const showPending=(force=false)=>{if(!force&&root.dataset.pageKey===pageKey){root.classList.add('page-pending');(root.querySelector('.app-content')||root.querySelector('main'))?.setAttribute('aria-busy','true');if((path==='/app'&&(!tab||tab==='messages'))||(path==='/admin'&&tab==='messages'))service.showPendingChat(qs().get('conversation'));}else mountPage(root,header()+pendingBody()+footer(),pageKey,{busy:true});};
  showPending();
  recordPaint('shell');
  try {
    if(!state.config) {
      // Read in parallel, then apply identity: its private-request cancellation must not abort config.
      const [config]=await Promise.all([api('/api/config'),sessionReader.read()]);
      if(version!==state.render)return;
      await session(version);
      if(version!==state.render)return;
      state.config=config;
      if(!localStorage.getItem('hireferry-language'))state.lang=state.config.default_language==='en'?'en':'zh';
      document.documentElement.lang=state.lang==='en'?'en':'zh-CN';showPending(true);
    }
    if(resumeCliLogin())return;
    let body;
    if(path==='/')body=home();
    else if(path==='/cli')body=renderCliGuide({config:state.config,origin:location.origin,lang:state.lang,esc,icon});
    else if(path==='/humangrant')body=humanGrant().intro();
    else if(/^\/human\/[A-Za-z0-9_-]+$/.test(path)){await session(version);if(version!==state.render)return;body=await humanGrant().reviewPage(path.split('/')[2],version);}
    else if(path==='/team/invite'){await session(version);if(version!==state.render)return;body=await team().reviewPage(location.hash.slice(1),version);}
    else if(path==='/login'){if(state.user||state.admin){go(afterSignIn());return;}body=login();}
    else if(path==='/jobs'||path==='/people'){await session(version);if(version!==state.render)return;go(state.user?'/app?tab=matches':'/login');return;}
    else if(/^\/jobs\/[^/]+$/.test(path))body=await jobDetail(decodeURIComponent(path.split('/')[2]));
    else if(/^\/people\/[^/]+$/.test(path))body=await personDetail(decodeURIComponent(path.split('/')[2]));
    else if(path==='/privacy'||path==='/terms')body=await legal(path.slice(1));
    else if(path==='/refunds')body=refundsPage();
    else if(path==='/contact')body=contactPage();
    else if(path==='/app'||path.startsWith('/app/')) {
      await session(version);if(version!==state.render)return;if(!state.user){go('/login');return;}
      if(path==='/app'&&!tab&&!qs().has('order')){const returnTo=afterSignIn();if(returnTo!=='/app'){go(returnTo);return;}}
      if(path==='/app/jobs/new')body=await jobEditor();
      else if(/^\/app\/jobs\/[^/]+\/edit$/.test(path))body=await jobEditor(decodeURIComponent(path.split('/')[3]));
      else if(qs().has('order')&&!tab)body=await paymentReturn();
      else if(tab==='messages')body=await service.messagesPage();
      else if(tab==='mandate')body=await service.mandatePage();
      else if(tab==='matches')body=await matchesPage();
      else if(tab==='orders')body=await ordersPage();
      else if(tab==='agents')body=await agentsPage();
      else if(tab==='webhooks')body=await service.webhooksPage();
      else if(tab==='profile')body=await profilePage();
      else if(tab==='jobs'&&state.user.role==='employer')body=await myJobs();
      else body=await service.messagesPage();
    }
    else if(path==='/admin'){await session(version);if(version!==state.render)return;body=await adminPage(tab||'overview');}
    else if(path==='/billing/return'||path==='/payment/return'||path==='/payment/success'||path==='/checkout/return'){await session(version);if(version!==state.render)return;body=await paymentReturn();}
    else body=`<main id="main" class="page-width page-error"><div class="eyebrow" style="justify-content:center">404 / A SMALL DETOUR</div><h1 style="margin-top:20px">${t('这条路，还没有渡口。','This path has no ferry yet.')}</h1><p>${t('页面不存在，或已经被移走。','This page does not exist or has been moved.')}</p><a href="/" data-nav class="button">${t('回到首页','Back to the beginning')}${icon('arrow')}</a></main>`;
    if(version!==state.render||resumeCliLogin())return;mountPage(root,header()+body+footer(),pageKey);syncCurrencyFields();recordPaint('ready');if(path==='/')void mountHome();
    if((path==='/app'&&(!tab||tab==='messages')&&!qs().has('order'))||(path==='/admin'&&tab==='messages'))service.mountChat();
    if(path.startsWith('/app')&&state.user?.role==='unassigned'&&!state.admin)chooseRole();
    if(location.hash){document.getElementById(location.hash.slice(1))?.scrollIntoView();}
    // Browsers without WebMCP need no eligibility request. Discovery never holds navigation open.
    if((document.modelContext||navigator.modelContext)?.registerTool&&state.user&&!state.admin&&!state.eligibility){
      void api('/api/ai/eligibility').then(eligibility=>{if(version!==state.render)return;state.eligibility=eligibility;registerWebMCP();}).catch(()=>{});
    }else registerWebMCP();
  } catch(error) {if(version!==state.render)return;const message=`<section class="route-error"><h1>${t('内容暂时无法加载','Content could not be loaded')}</h1><p>${esc(error.message)}</p><button class="button" data-action="retry">${t('重试','Try again')}${icon('arrow')}</button></section>`;const body=path==='/admin'&&state.admin?shell(message,tab||'overview',true):path.startsWith('/app')&&state.user?shell(message,tab||'messages'):`<main id="main" class="page-width">${message}</main>`;mountPage(root,header()+body+footer(),pageKey);recordPaint('error');}
}

async function adminPage(tab) {
  if(state.bootstrap&&!state.admin)return `<main id="main" class="page-width admin-auth"><div class="admin-auth-top"><span class="icon-badge">${icon('key')}</span><h1>${t('绑定第一把通行密钥','Add your first passkey')}</h1><p>${t('完成后，管理员登录只接受通行密钥。','After this step, administrator sign-in uses passkeys only.')}</p></div><section class="auth-card"><h2>${t('安全地开始。','A secure beginning.')}</h2><p class="subtitle">${t('使用设备指纹、面容或实体安全密钥。一次性密码不会再用于登录。','Use your device’s fingerprint, face recognition, or security key. The one-time password cannot be used to sign in again.')}</p><form data-form="passkey-register"><div class="field"><label for="passkey-name">${t('密钥名称','Passkey name')}</label><input class="input" id="passkey-name" name="name" value="${t('我的主设备','My primary device')}" maxlength="80" required></div><button class="button full" type="submit">${icon('key')}${t('绑定通行密钥','Create a passkey')}</button></form><p class="help">${t('请在可信设备上操作。首次绑定完成后可以再添加备用密钥。','Use a trusted device. You can add backup passkeys after this first one.')}</p></section></main>`;
  if(!state.admin){const s=await api('/api/admin/auth/status');return `<main id="main" class="page-width admin-auth"><div class="admin-auth-top"><span class="icon-badge">${icon('shield')}</span><h1>${t('聘渡总控台','HireFerry control room')}</h1><p>${t('每次相遇背后，都有人认真负责。','Real people, behind every connection.')}</p></div><section class="auth-card"><h2>${s.initialized?t('欢迎回来。','Welcome back.'):t('第一次，安全启程。','A secure first step.')}</h2><p class="subtitle">${s.initialized?t('使用已绑定的通行密钥登录。','Sign in with a registered passkey.'):t('输入在服务器上生成的一次性密码。','Enter the one-time password generated on the server.')}</p>${s.initialized?`<button class="button full" data-action="admin-passkey-login">${icon('key')}${t('使用通行密钥登录','Sign in with a passkey')}</button><p class="help">${t('支持已绑定的指纹、面容与实体安全密钥。','Supports registered device biometrics and security keys.')}</p><div class="separator">${t('团队员工','Team staff')}</div><a href="/login" data-nav class="button secondary full">${icon('mail')}${t('使用受邀邮箱登录','Sign in with your invited email')}</a><p class="help">${t('请先接受管理员发给你的邀请，再使用自己的账户登录。','Accept the administrator’s invitation first, then sign in with your own account.')}</p>`:`<form data-form="admin-bootstrap"><div class="field"><label for="bootstrap-password">${t('一次性密码','One-time password')}</label><input class="input" type="password" id="bootstrap-password" name="password" autocomplete="one-time-code" required></div><button class="button full" type="submit">${t('验证并绑定通行密钥','Verify and add a passkey')}${icon('arrow')}</button></form><p class="help">${t('管理员需要先在 Linux 服务器中运行初始化命令。密码短期有效，仅用于首次绑定。','An administrator must run the initialization command on the Linux server first. The password expires soon and is only for the first passkey setup.')}</p>`}</section></main>`;}
  if(['team','keys','agents'].includes(tab)&&!state.super_admin)return shell(`${heading(t('此页面由超级管理员管理','This page is managed by the super administrator'),t('你可以继续在消息、匹配及其他业务页面协作。','Continue working in messages, introductions, and other business pages.'))}<a class="button" href="/admin?tab=messages" data-nav>${t('打开消息','Open messages')}${icon('arrow')}</a>`,'messages',true);
  if(tab==='team')return team().teamPage();if(tab==='messages')return service.messagesPage(true);if(tab==='mandates')return service.adminMandates();if(tab==='agents')return service.adminTokens();if(tab==='users')return adminUsers();if(tab==='jobs')return adminJobs();if(tab==='orders')return adminOrders();if(tab==='keys')return adminKeys();if(tab==='matches')return matchesPage(true);return adminOverview();
}
function dateFilter(tab,extra='') {return `<form data-form="admin-filter" data-tab="${tab}" class="filter-row"><label>${t('开始 (UTC)','From (UTC)')} <input class="input" type="date" name="from" value="${esc(qs().get('from')||'')}"></label><label>${t('结束 (UTC)','To (UTC)')} <input class="input" type="date" name="to" value="${esc(qs().get('to')||'')}"></label>${extra}<button class="button secondary small" type="submit">${t('查看','Apply')}</button><a href="/admin?tab=${tab}" data-nav class="text-button">${t('历史全部','All time')}</a></form>`;}
function apiFilter(path) {const p=new URLSearchParams();for(const k of ['from','to','status','q','role','page','mode','currency'])if(qs().get(k))p.set(k,qs().get(k));return path+(p.size?'?'+p:'');}
function chartSvg(series,record) {
  if(!series?.length)return `<div class="chart-empty">${t('所选时间范围内还没有已确认的收款或退款。','No confirmed payments or refunds in this date range yet.')}</div>`;
  let items=series.map(x=>({...x,revenue_cents:Number(x.revenue_cents)||0})).sort((a,b)=>a.date.localeCompare(b.date));
  const monthly=items[0].date.length===7;
  const stamp=d=>Date.parse(d+(d.length===7?'-01T00:00:00Z':'T00:00:00Z'));
  const start=stamp(items[0].date),finish=stamp(items.at(-1).date);
  const byDate=new Map(items.map(x=>[x.date,x])),expanded=[];
  const cursor=new Date(start),limit=monthly?1200:400;
  while(cursor.getTime()<=finish&&expanded.length<=limit){const key=cursor.toISOString().slice(0,monthly?7:10);expanded.push(byDate.get(key)||{date:key,revenue_cents:0,orders:0});if(monthly)cursor.setUTCMonth(cursor.getUTCMonth()+1);else cursor.setUTCDate(cursor.getUTCDate()+1);}
  if(expanded.length<=limit)items=expanded;
  const rawMin=Math.min(0,...items.map(x=>x.revenue_cents)),rawMax=Math.max(0,...items.map(x=>x.revenue_cents));
  const desiredStep=Math.max(4,rawMax-rawMin)/4,scale=10**Math.floor(Math.log10(desiredStep)),fraction=desiredStep/scale;
  const step=Math.max(1,Math.ceil((fraction<=1?1:fraction<=2?2:fraction<=2.5?2.5:fraction<=5?5:10)*scale));
  const ymin=Math.floor(rawMin/step)*step,ymax=Math.ceil(rawMax/step)*step||(rawMin===0?4*step:0);
  const ticks=Array.from({length:Math.round((ymax-ymin)/step)+1},(_,i)=>ymin+i*step);
  const w=760,h=215,l=Math.max(58,Math.min(135,Math.max(...ticks.map(value=>money(value,record).length*6+17)))),r=18,top=15,bottom=32,plotw=w-l-r,ploth=h-top-bottom;
  const yFor=value=>top+ploth-((value-ymin)/(ymax-ymin))*ploth;
  const point=x=>[l+(finish>start?(stamp(x.date)-start)/(finish-start):.5)*plotw,yFor(x.revenue_cents)];
  const points=items.map(point),path=points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');
  return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${monthly?t('按月净收款图表。净额等于收款减成功退款，可以为负。','Monthly net receipts: payments minus successful refunds. Values may be negative.'):t('按日净收款图表。净额等于收款减成功退款，可以为负。','Daily net receipts: payments minus successful refunds. Values may be negative.')}">${ticks.map(value=>{const y=yFor(value);return `<line class="chart-grid${value===0?' chart-zero':''}" x1="${l}" x2="${w-r}" y1="${y}" y2="${y}"/><text x="${l-10}" y="${y+3}" text-anchor="end">${esc(money(value,record))}</text>`;}).join('')}<path class="chart-area" d="${path} L${points.at(-1)[0]},${yFor(0)} L${points[0][0]},${yFor(0)} Z"/><path class="chart-line" d="${path}"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${items.length<35?2.5:0}" fill="var(--accent)"><title>${esc(items[i].date)} · ${esc(t('净额','Net'))} ${esc(money(items[i].revenue_cents,record))}</title></circle>`).join('')}${items.filter((x,i)=>i===0||i===items.length-1||i%Math.max(1,Math.ceil(items.length/6))===0).map(x=>`<text x="${point(x)[0]}" y="${h-7}" text-anchor="middle">${esc(x.date.slice(5))}</text>`).join('')}</svg>`;
}
function reportingCurrencySelect(report) {
  const codes=[...new Set([...currencies().map(item=>item.currency),...(report.currency_totals||[]).map(item=>item.currency),currency(report).currency])];
  return `<label>${t('统计币种','Reporting currency')}<select class="input" name="currency">${codes.map(code=>`<option value="${esc(code)}" ${code===currency(report).currency?'selected':''}>${esc(code)}</option>`).join('')}</select></label>`;
}
function currencyTotals(rows) {
  if(!rows.length)return '';
  return `<section class="panel"><div class="panel-header"><div><h2>${t('按币种查看收款','Receipts by currency')}</h2><p>${t('与当前日期和实收／测试筛选一致。币种分别统计，不换算、不相加。','Uses the selected dates and live/test mode. Currencies are reported separately, without conversion or a combined total.')}</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('币种','Currency')}</th><th>${t('收款','Payments')}</th><th>${t('成功退款','Successful refunds')}</th><th>${t('净额','Net receipts')}</th><th>${t('付款订单数','Paid orders')}</th></tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${esc(row.currency)}</th><td>${money(row.gross_cents,row)}</td><td>${money(row.refund_cents,row)}</td><td>${money(row.revenue_cents,row)}</td><td>${Number(row.paid_orders)||0}</td></tr>`).join('')}</tbody></table></div></section>`;
}

async function adminOverview() {const d=await api(apiFilter('/api/admin/overview'));const s=d.stats;const stats=[['users','person',t('全部用户','People'),String(s.users||0),t('求职者与招聘方','Seekers and employers')],['revenue','wallet',d.payment_mode==='test'?t('测试流水 · 净额','Test net receipts'):t('实收净额','Net receipts'),money(s.revenue_cents,d),d.payment_mode==='test'?t('测试收款减测试退款','Test payments less test refunds'):t('所选时间内的收款减退款','Payments less refunds in the selected range')],['jobs','briefcase',t('招聘中岗位','Open roles'),String(s.active_jobs||0),t('正在寻找合适的人','Ready for the right person')],['orders','receipt',t('已支付订单','Paid orders')+' · '+currency(d).currency,String(s.paid_orders||0),`${s.pending_orders||0} ${t('笔待支付（全部币种）','pending across all currencies')}`]];return shell(`${heading(t('每次相遇，尽在眼前。','Every connection, in view.'),t('一个简单的总控台，让服务有条不紊。','A simple control room to keep good things moving.'),'','THE CONTROL ROOM')}<div class="panel-header">${dateFilter('overview',`${reportingCurrencySelect(d)}<select class="input" name="mode" aria-label="${t('流水类型','Payment mode')}"><option value="live" ${d.payment_mode==='live'?'selected':''}>${t('实收流水','Live payments')}</option><option value="test" ${d.payment_mode==='test'?'selected':''}>${t('测试流水','Test payments')}</option></select>`)}<span class="pill">${icon('clock')}${qs().get('from')?t('自选时间','Custom range'):t('历史以来','All time')}</span></div><section class="stat-grid">${stats.map(([id,ico,label,val,cap])=>`<article class="stat"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${esc(val)}</div><div class="stat-caption">${esc(cap)}</div></article>`).join('')}</section>${s.review_orders?notice(`${s.review_orders} ${t('笔已收款订单等待人工核对，请在订单页查看。','paid orders need review. Check the order page.')}`,'warning'):''}<section class="panel chart-panel"><div class="chart-header"><h2>${t('净收款，随时间展开。','Net receipts over time.')}</h2><div class="chart-legend"><span><span class="legend-dot"></span>${d.payment_mode==='test'?t('测试净额','Test net receipts'):t('实收净额','Net receipts')} · ${esc(d.currency||currency().currency)}</span></div></div>${chartSvg(d.series,d)}<div class="chart-summary"><span>${t('收款','Payments')}<strong>${money(s.gross_cents,d)}</strong></span><span>${t('成功退款','Successful refunds')}<strong>${money(s.refund_cents,d)}</strong></span><span>${t('净额','Net receipts')}<strong>${money(s.revenue_cents,d)}</strong></span></div><div class="chart-summary chart-breakdown">${(d.revenue_by_kind||[]).map(k=>`<span>${kindText(k.kind)}<strong>${money(k.amount_cents,d)}</strong></span>`).join('')}</div><p class="help">${t('收款与成功退款按各自确认时间计入。某天只有退款时，净额可以为负。','Payments and successful refunds are counted at their respective confirmation times. A day with only refunds has negative net receipts.')}</p></section>${currencyTotals(d.currency_totals||[])}<section class="panel"><div class="panel-header"><div><h2>${t('最近的订单','Recent orders')}</h2><p>${t('每一笔，都清楚可查。','Every payment, accounted for.')}</p></div><a href="/admin?tab=orders" data-nav class="text-button">${t('查看全部','View all')}${icon('arrow')}</a></div>${orderTable(d.recent_orders||[])}</section><div class="mini-grid" style="margin-top:20px"><section class="panel"><div class="panel-header"><h2>${t('双方的期待','Both sides of the crossing')}</h2>${icon('person')}</div><div class="summary-kpi"><span>${t('求职者','Job seekers')}</span><strong>${s.seekers||0}</strong></div><div class="summary-kpi"><span>${t('招聘方','Employers')}</span><strong>${s.employers||0}</strong></div><div class="summary-kpi"><a href="/admin?tab=matches" data-nav class="text-button">${t('管理人工对接','Manage introductions')}${icon('arrow')}</a></div></section><section class="panel"><div class="panel-header"><h2>${t('从这里继续','Keep things moving')}</h2></div><p class="help">${t('查看新简历，了解新岗位。认真判断双方的需要，再发起对接。','Review new résumés and roles. Understand what each side needs before making an introduction.')}</p><div class="check-list"><a class="text-button" href="/admin?tab=users" data-nav>${t('查看用户与简历','Review people and résumés')}${icon('arrow')}</a><a class="text-button" href="/admin?tab=jobs" data-nav>${t('查看招聘岗位','Review open roles')}${icon('arrow')}</a></div></section></div>`,'overview',true);}
function orderTable(items) {return items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('订单','Order')}</th><th>${t('类型','Type')}</th><th>${t('金额','Amount')}</th><th>${t('状态','Status')}</th><th>${t('支付方式','Provider')}</th><th>${t('时间','Created')}</th></tr></thead><tbody>${items.map(o=>`<tr><td><span class="order-number" title="${esc(o.id)}">${esc(o.id.slice(0,12))}</span></td><td>${kindText(o.kind)}</td><td class="money">${money(o.amount_cents,o)}${orderRefundDetails(o)}</td><td>${orderBadge(o)}</td><td>${esc(providerText(o.provider))} ${o.live_mode===false&&o.provider!=='free'?`<span class="test-badge">${t('测试','Test')}</span>`:''}</td><td>${date(o.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty(t('还没有订单。','No orders yet.'),t('实际交易发生后，记录会出现在这里。','Actual transactions will appear here.'),'','receipt');}
async function adminUsers() {const d=await api(apiFilter('/api/admin/users'));return shell(`${heading(t('每个账户，背后都是一个人。','Every account belongs to a person.'),t('查看资料，处理违规，并协助双方完善信息。','Review profiles, handle abuse, and help people move forward.'),'','PEOPLE')}<section class="panel"><div class="panel-header"><form data-form="admin-users-search" class="filter-row"><div class="search-field">${icon('search')}<input class="input" name="q" value="${esc(qs().get('q')||'')}" placeholder="${esc(t('搜索名称或邮箱','Search name or email'))}" aria-label="${t('搜索用户','Search people')}"></div><select class="input" name="role" aria-label="${t('用户身份','User role')}"><option value="">${t('全部身份','All roles')}</option><option value="seeker" ${qs().get('role')==='seeker'?'selected':''}>${t('求职者','Job seekers')}</option><option value="employer" ${qs().get('role')==='employer'?'selected':''}>${t('招聘方','Employers')}</option></select><select class="input" name="status" aria-label="${t('账户状态','Account access')}"><option value="">${t('全部状态','All access states')}</option><option value="active" ${qs().get('status')==='active'?'selected':''}>${t('正常','Active')}</option><option value="suspended" ${qs().get('status')==='suspended'?'selected':''}>${t('已封禁','Suspended')}</option></select><button class="button secondary small">${t('搜索','Search')}</button></form></div>${d.items?.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('用户','Person')}</th><th>${t('身份','Role')}</th><th>${t('状态','Status')}</th><th>${t('注册时间','Joined')}</th><th>${t('操作','Action')}</th></tr></thead><tbody>${d.items.map(u=>`<tr><td><div class="table-person">${avatar(u,'small')}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div></td><td>${roleText(u.role)}</td><td>${badge(u.banned?'banned':'active')}</td><td>${date(u.created_at)}</td><td><button class="text-button" data-action="admin-edit-user" data-id="${esc(u.id)}">${t('资料','Profile')} →</button><button class="text-button" data-action="admin-user-access" data-id="${esc(u.id)}">${u.banned?t('恢复访问','Restore access'):t('封禁','Suspend')}</button></td></tr>`).join('')}</tbody></table></div><p class="help">${d.total??d.items.length} ${t('位用户','people')}</p>${pagination(d.total,d.page_size??d.limit)}`:empty(t('暂时没有找到用户。','No people found.'),t('可以试试其他搜索条件。','Try another search.'),'','person')}</section>`,'users',true);}
async function editUser(id) {const u=await api(`/api/admin/users/${encodeURIComponent(id)}`);if(!u)throw new Error(t('未找到这个用户，请刷新后重试。','This person was not found. Refresh and try again.'));openDialog(`<div class="eyebrow">MANAGE PROFILE</div><h2 id="dialog-title">${esc(u.name||u.email)}</h2><p class="dialog-intro">${esc(u.email)} · ${roleText(u.role)}</p><form data-form="admin-user" data-id="${esc(u.id)}"><div class="grid-2"><div class="field"><label>${t('显示名称','Display name')}<input class="input" name="name" value="${esc(u.name)}" maxlength="100" required></label></div><div class="field"><label>${t('联系邮箱','Contact email')}<input class="input" name="public_email" type="email" value="${esc(u.public_email)}" maxlength="254"></label></div></div>${u.role==='seeker'?`<div class="field"><label>${t('简历 · Markdown','Résumé · Markdown')}<textarea class="input code" name="resume_md" maxlength="60000" rows="10">${esc(u.resume_md)}</textarea></label></div>`:''}<p class="help">${t('封禁和恢复访问请在用户列表中单独操作。保存资料不会改变账户状态。','Manage suspension separately from the user list. Saving this profile does not change account access.')}</p><div class="form-actions">${u.role==='seeker'?`<button type="button" class="button danger small" data-action="delete-resume" data-id="${esc(u.id)}">${t('删除简历','Delete résumé')}</button>`:''}<button type="submit" class="button">${t('保存修改','Save changes')}${icon('check')}</button></div></form>`,{wide:true});}
async function userAccessDialog(id) {
  const version=state.render;
  const {user,access}=await api(`/api/admin/users/${encodeURIComponent(id)}/access`);
  if(version!==state.render)return;
  const banned=!access.banned;
  const consequence=banned?t('封禁后立即退出此账户的所有登录，并撤销 AI 令牌。该账户不能继续登录、访问匹配资料或发送消息；通知投递也会停止。','Suspension ends all sign-ins and revokes AI tokens. The account cannot sign in, view introduced profiles or send messages. Event deliveries also stop.'):t('恢复后需要重新登录、重新创建 AI 令牌。旧会话和已撤销的令牌不会恢复。','The person must sign in again and create new AI tokens. Old sessions and revoked tokens will stay invalid.');
  openDialog(`<div class="eyebrow">${t('账户访问','ACCOUNT ACCESS')}</div><h2 id="dialog-title">${banned?t('封禁这个账户？','Suspend this account?'):t('恢复这个账户的访问？','Restore account access?')}</h2><p class="dialog-intro">${esc(user.name||user.email)} · ${esc(user.email)}</p>${notice(consequence,banned?'warning':'')}<form data-form="admin-user-access" data-id="${esc(id)}" data-banned="${banned}"><div class="field"><label for="access-reason">${t('操作原因（会记录到审计日志）','Reason (recorded in the audit log)')}</label><textarea class="input" id="access-reason" name="reason" maxlength="500" rows="3" required></textarea></div>${access.reason?`<p class="help">${t('上次操作原因','Previous reason')}：${esc(access.reason)}${access.changed_at?' · '+date(access.changed_at):''}</p>`:''}<div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">${t('取消','Cancel')}</button><button type="submit" class="button ${banned?'danger':''}">${banned?t('确认封禁','Suspend account'):t('恢复访问','Restore access')}</button></div></form>`);
}

async function adminJobs() {
  const d=await api(apiFilter('/api/admin/jobs'));
  jobCache.clear();(d.items||[]).forEach(job=>jobCache.set(job.id,job));
  return shell(`${heading(t('让每个机会，清楚可信。','Keep every opportunity clear.'),t('审核内容与招聘人数。回收站岗位可恢复一次，管理员删除为永久删除。','Review descriptions and hiring targets. A role in the trash can be restored once; administrator deletion is permanent.'),'','JOBS')}<section class="panel">${d.items?.length?`<div class="list">${d.items.map(j=>`<article class="list-row"><div><h3>${esc(j.title||t('已永久删除的岗位','Permanently deleted role'))}</h3><div class="list-meta">${jobBadge(j)}<span class="job-salary">${money(j.salary_cents,j)} <small>/ ${t('月底薪','month, base')}</small></span><span>${headcountText(j)}</span><span>${t('描述已修改','Description updates')} ${j.edits_used}</span></div></div><div class="row-actions"><button class="text-button" data-action="admin-edit-job" data-id="${esc(j.id)}">${t('管理','Manage')} →</button></div></article>`).join('')}</div>${pagination(d.total,d.page_size??d.limit)}`:empty(t('还没有岗位。','No roles yet.'),t('招聘方创建岗位后，会显示在这里。','Roles appear here after an employer creates them.'),'','briefcase')}</section>`,'jobs',true);
}
async function editAdminJob(id) {
  const j=await api(`/api/admin/jobs/${encodeURIComponent(id)}`);
  if(!j)throw new Error(t('未找到岗位。','Role not found.'));
  jobCache.set(j.id,j);
  const intro=`<div class="eyebrow">MANAGE OPPORTUNITY</div><h2 id="dialog-title">${esc(j.title||t('已永久删除的岗位','Permanently deleted role'))}</h2><p class="dialog-intro">${money(j.salary_cents,j)} / ${t('月底薪，标题与底薪不能修改。','month base. The title and salary cannot be changed.')}</p><div class="list-meta job-admin-meta">${jobBadge(j)}<span>${headcountText(j)}</span></div>`;
  if(j.status==='deleted') {
    openDialog(`${intro}${notice(Number(j.delete_count)===1?t('此岗位在回收站，可免费恢复一次；管理员也可以将其永久删除。','This role is in the trash. It can be restored once for free, or permanently deleted by an administrator.'):t('岗位标题与正文已永久清除，不能恢复。必要的订单与安全关联记录保留。','The title and description have been permanently erased and cannot be restored. Necessary order and security records remain.'))}${Number(j.delete_count)===1?`<div class="form-actions"><button type="button" class="button danger small" data-action="admin-delete-job" data-id="${esc(id)}">${t('永久删除','Delete permanently')}</button><button type="button" class="button" data-action="admin-restore-job" data-id="${esc(id)}">${t('免费恢复一次','Restore once for free')}${icon('back')}</button></div>`:''}`,{wide:true});
    return;
  }
  if(j.status==='draft') {
    openDialog(`${intro}${notice(t('这是尚未完成发布付款的草稿。内容与人数由招聘方管理，管理员可以永久删除。','This draft has not completed publication payment. Its employer manages the content and hiring target; administrators can permanently delete it.'))}<div class="field"><label>${t('岗位描述 · 只读','Job description · read-only')}<textarea class="input code" rows="10" readonly>${esc(j.jd_md)}</textarea></label></div><div class="form-actions"><button type="button" class="button danger small" data-action="admin-delete-job" data-id="${esc(id)}">${t('永久删除岗位','Delete role permanently')}</button></div>`,{wide:true});
    return;
  }
  openDialog(`${intro}${headcountControl(j,true)}${['draft','published'].includes(j.status)?`<p class="help job-admin-headcount-help">${t('人数可免费无限次修改，不占描述修改次数。0 只暂停新匹配，原有匹配与会话保留。','Change the target free of charge as often as needed, without using a description update. Zero pauses new introductions; existing introductions and chats remain.')}</p><hr>`:''}<form data-form="admin-job" data-id="${esc(id)}"><div class="field"><label>${t('岗位描述 · Markdown','Job description · Markdown')}<textarea name="jd_md" class="input code" rows="12" maxlength="60000">${esc(j.jd_md)}</textarea></label></div><div class="field"><label>${t('岗位状态','Role status')}<select name="status" class="input"><option value="${esc(j.status)}">${j.status==='published'?t('已发布','Published'):statusText(j.status)}</option>${j.status==='published'||j.status==='draft'?`<option value="closed">${t('永久关闭招聘','Close hiring permanently')}</option>`:''}</select></label><p class="help">${t('只想暂停新匹配，请把人数改为 0。关闭后不能通过增加人数重新招聘。','To pause new introductions, set the target to 0. A closed role cannot resume hiring by increasing its target.')}</p></div><div class="form-actions"><button type="button" class="button danger small" data-action="admin-delete-job" data-id="${esc(id)}">${t('永久删除岗位','Delete role permanently')}</button><button type="submit" class="button">${t('保存内容与状态','Save content and status')}${icon('check')}</button></div></form>`,{wide:true});
}
async function adminOrders() {const d=await api(apiFilter('/api/admin/orders'));return shell(`${heading(t('资金往来，一目了然。','A clear record of every payment.'),t('按时间查看订单。已收款异常订单需人工核对。','Filter orders by time. Review paid orders that need attention.'),'','ORDERS & PAYMENTS')}<section class="panel"><div class="panel-header">${dateFilter('orders',`<select class="input" name="status" aria-label="${t('订单状态','Order status')}"><option value="">${t('全部状态','All statuses')}</option>${['pending','paid','paid_needs_review','partially_refunded','refunded','failed','cancelled'].map(s=>`<option value="${s}" ${qs().get('status')===s?'selected':''}>${statusText(s)}</option>`).join('')}</select>`)}</div>${orderTable(d.items||[])}${pagination(d.total,d.page_size??d.limit)}<p class="help" style="margin-top:20px">${t('金额保留订单原币种，不作汇率换算。原付款与累计成功退款分别记录，净额扣除已确认的退款。退款请通过支付服务商商户后台处理，本站不发起退款。','Amounts keep each order’s original currency, without conversion. Original payments and successful refunds are recorded separately; net amounts deduct confirmed refunds. Process refunds in the payment provider’s merchant dashboard; this site does not initiate them.')}</p></section>`,'orders',true);}
async function adminKeys() {const d=await api('/api/admin/passkeys');return shell(`${heading(t('守好每一把钥匙。','Keep the keys in good hands.'),t('管理员只通过通行密钥登录。建议绑定至少两把。','Administrators sign in with passkeys only. Keep at least two registered.'),'','PASSKEYS')}<section class="panel"><div class="panel-header"><div><h2>${t('已绑定的通行密钥','Registered passkeys')}</h2><p>${t('添加或删除密钥需要近期身份验证。','Adding or removing passkeys requires recent authentication.')}</p></div><button class="button secondary small" data-action="admin-reauth">${icon('shield')}${t('重新验证','Verify again')}</button></div><div class="list">${(d.passkeys||[]).map(k=>`<div class="list-row"><div><h3>${esc(k.name)}</h3><div class="list-meta"><span>${t('绑定于','Added')} ${date(k.created_at)}</span><span>${t('最近使用','Last used')} ${date(k.last_used_at)}</span></div></div><button class="text-button" data-action="delete-passkey" data-id="${esc(k.id)}" ${(d.passkeys||[]).length<2?'disabled':''}>${t('移除','Remove')}</button></div>`).join('')}</div><hr><form data-form="passkey-register"><div class="grid-2"><div class="field"><label for="passkey-name">${t('新密钥名称','New passkey name')}</label><input class="input" id="passkey-name" name="name" maxlength="80" placeholder="${esc(t('例如：备用安全密钥','For example: Backup security key'))}" required></div><div class="field" style="align-self:end"><button class="button" type="submit">${icon('plus')}${t('绑定另一把密钥','Add another passkey')}</button></div></div></form><p class="help">${t('不能删除最后一把通行密钥。密钥私密部分保存在你的设备中，本站仅保存公钥。','The last passkey cannot be removed. Its private part stays on your device; this site stores the public key.')}</p></section>`,'keys',true);}
